COLLDATA("jamulfawaid","ur",[[496,"سیدنا انس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے اہل قبا کو فرمایا: طہارت کے حوالے سے اللہ تعالیٰ نے تمہاری خوبی بیان فرمائی ہے تو تمہاری طہارت کا کیا طریقہ ہے؟ انہوں نے کہا ہم استنجا میں پانی اور پتھر کا استعمال کرتے ہیں۔ (رزین)","",{"k":"رزین، دیگر روایات بھی آتی ہیں جو کہ ضعیف ہیں۔ (مرعاۃ: 1/435)"}],[497,"عویم رضی اللہ عنہ سے روایت ہے کہ لوگوں نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم ہم تو کچھ نہیں جانتے البتہ یہ کہ ہمارے چند ہمسائے یہودی اپنی دبر پانی سے دھوتے ہیں جب قضائے حاجت کرتے تھے پس ہم نے بھی دھونا شروع کر دیا جیسے وہ دھوتے تھے۔","",{"k":"احمد (15059)۔ طبرانی فی الثلاثۃ اس میں شرحبیل بن سعد ضعیف ہے۔ ہیثمی (1054)"}],[498,"محمد بن عبد اللہ بن سلام سے روایت ہے کہ اہل قباء نے عرض کی: یا رسول اللہ! ہمارے پاس تورات میں پانی کے ساتھ استنجاء کرنے کے لیے لکھا ہوا ہے۔","",{"k":"احمد (23321)۔ انقطاع ہے، محمد نے عن ابیہ نہیں کہا، اور شہر بن حوشب بھی ہے جو کہ مدلس ہے۔"}],[499,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص رفع حاجت کے لیے جائے تو تین پتھر لیتا جائے اور ان کے ساتھ طہارت کرے تو یہ اس کے لیے کفایت کرتے ہیں۔‘‘ (ابو داؤد، نسائی)","",{"k":"ابوداود (40)۔ دارمی (670)۔ حسن البانی: 31۔","m":"يَسْتَطِيبُ استفعال سے مضارع معلوم واحد مذکر غائب، استنجاء کرے۔ بِهِنَّ ان پتھروں کے ساتھ۔ فَإِنَّهَا یہ پتھر۔ تُجْزِئُ افعال سے مضارع معلوم واحد مونث غائب، کفایت کرتے ہیں۔ عَنْهُ استنجاء سے یا پانی سے۔","e":"۱۔ اس سے یہ ثابت ہوا کہ استنجاء کے لیے کم از کم تین پتھروں یا ڈھیلوں کا استعمال ضروری ہے۔ ۲۔ اگر چہ پانی سے استنجاء نہ بھی کیا جائے پتھروں سے کیا جائے اور ان سے پاخانہ یا پیشاب کے اثرات ختم ہو جائیں تو یہ صفائی کے لیے کافی ہیں۔ علامہ ڈیانوی رحمہ اللہ فرماتے ہیں: وَقَالَ أَكْثَرُ أَهْلِ الْعِلْمِ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَنْ بَعْدَهُمْ إِنَّ الْإِسْتِنْجَاءَ بِالْحِجَارَةِ يَجْزِى وَإِنْ لَّمْ يُسْتَنْعَ بِالْمَاءِ إِذَا أَنْقَى أَثَرَ الْغَائِطِ وَالْبَوْلِ. (عون المعبود: ۱۵/۱) ’’اکثر اہل علم صحابہ کرام رضی اللہ عنہم اور ان کے بعد والوں کا قول ہے کہ پتھروں کے ساتھ استنجاء کرنا کفایت کر جاتا ہے اگر چہ پانی کے ساتھ استنجاء نہ بھی کیا جائے، شرط یہ ہے کہ قضائے حاجت اور پیشاب کے اثرات صاف ہو جائیں۔‘‘"}],[500,"سیدنا سہل بن سعد رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے استنجا کے بارے میں سوال کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے کسی آدمی کو تین پتھر نہیں میسر آتے دو پتھر مقعد کے دو اطراف کے لیے اور ایک سوراخ کے لیے۔‘‘ (الکبیر)","",{"k":"طبرانی کبیر: 5697۔ وفیہ عتیق بن یعقوب زہری، انہ حفظ الموطا فی حیاة مالک ہیثمی: 1048۔ ابن حجر رحمہ اللہ نے اسے ضعیف قرار دیا ہے۔ التلخیص الحبیر: 111/1۔"}],[501,"سیدنا عبداللہ ابن مسعود رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم کو رفع حاجت کی ضرورت پیش آئی تو آپ نے مجھے حکم دیا کہ میں تین پتھر لاؤں۔ مجھے دو پتھر ہاتھ آئے اور تیسرا تلاش کرنے پر میسر نہ آیا تو میں ایک لید اٹھا لایا۔ آپ صلی اللہ علیہ وسلم نے دونوں پتھر لے لیے اور لید پھینک دی اور ساتھ ہی فرمایا: ’’یہ ناپاک ہے۔‘‘ اور یہ جنات کی خوراک ہے۔","",{"k":"بخاری (156)۔ ترمذی (17)۔ نسائی (42)۔ ابن ماجہ (314)۔ احمد (4421)۔","m":"آتِيَهُ أَتَى يَأْتِي سے مضارع معلوم واحد متکلم، میں لے کر آؤں، مفعول بہ ضمیر نبی اکرم صلی اللہ علیہ وسلم کی جانب لوٹتی ہے۔ بِهَا وہ تین پتھر۔ رِكْسٌ پلید ہے۔","e":"اس سے ثابت ہوتا ہے کہ ڈھیلے کم از کم تین استعمال کیے جائیں اور لید یا گوبر سے استنجاء نہ کیا جائے۔ جو لید آپ صلی اللہ علیہ وسلم نے پھینک دی تھی وہ گدھے کی تھی۔ (ابن خزیمہ) بعض لوگوں نے استنجاء کے لیے تین ڈھیلوں کے پابند نہ ہونے کا استدلال کیا ہے کہ آپ صلی اللہ علیہ وسلم نے جب وہ لید پھینک دی تو باقی دو پتھر رہ گئے تھے اس لیے تین کا ہونا ضروری نہیں۔ حافظ ابن حجر رحمہ اللہ نے اس کا جواب دیا ہے کہ مسند احمد میں آتا ہے کہ آپ صلی اللہ علیہ وسلم نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے کہا تھا: ائْتِنِي بِحَجَرٍ اس لید کی جگہ میرے لیے پتھر لے کر آؤ، اس سے پتہ چلتا ہے کہ آپ نے تین پتھر مکمل کروائے تھے۔ (فتح الباری: ۱/۲۵۷)"}],[502,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’لید کے ساتھ استنجا نہ کرو اور نہ ہڈی کے ساتھ، یہ تمہارے جن بھائیوں کی خوراک ہے۔‘‘","",{"k":"ترمذی (18)۔ مسلم (450)۔ احمد (4268)۔ صحیح، البانی: 17۔","m":"لَا تَسْتَنْجُوا استفعال سے نہی حاضر جمع مذکر، استنجاء نہ کرو۔ بِالرَّوْثِ لید، یا گوبر۔ بِالْعِظَامِ، عَظْم کی جمع ہے، ہڈیاں۔ فَإِنَّهَا یہ ضمیر عظام اور روث کی طرف لوٹتی ہے۔ زَادُ خوراک۔","e":"اس سے جہاں یہ ثابت ہوا کہ گوبر جنوں کے جانوروں کی خوراک ہے، اور ہڈیاں جنوں کی خوراک ہے، اس لیے ان کے ساتھ استنجاء نہ کیا جائے وہاں یہ بھی پتہ چلا کہ جن کھاتے بھی ہیں اور ان میں سے مسلمان بھی ہیں۔"}],[503,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ جنات نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور انہوں نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! اپنی امت کو منع فرمائیں ہڈی، لید اور کوئلہ کے ساتھ استنجا کرنے سے۔ اللہ نے ان اشیاء میں ہمارے لیے رزق رکھا ہے، چنانچہ نبی صلی اللہ علیہ وسلم نے ہمیں اس سے منع فرمایا۔","",{"k":"ابوداود (39)۔ مسلم (450)۔ ترمذی (18)۔ صحیح، البانی: 30۔","m":"وَفْدُ جو گروہ جمع ہو کر آئے، اس کی جمع وُفُوْدٌ ہے، یہ ہجرت سے پہلے آئے تھے، نصیبین مقام کے رہنے والے تھے۔ اِنْهَ انہی ینھی سے امر واحد مذکر حاضر ہے، منع کر دو۔ حُمَمَةٌ حاء پر ضمہ اور دونوں میم پر فتح ہے، جلی ہوئی لکڑی، یعنی کوئلہ۔"}],[504,"سیدنا انس رضی اللہ عنہ سے مرفوع روایت ہے (کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا) نصیبین کے جنات کے وفد نے مجھ سے زادراہ طلب کیا ہے لہذا تم ہڈی اور لید کے ساتھ استنجا نہ کیا کرو وہ تمہارے جن بھائیوں کی خوراک ہے۔ لوگوں نے عرض کی: اس سے ان کو کیا فائدہ ہوگا؟ فرمایا: ’’وہ جس ہڈی کے پاس سے گذرتے ہیں اس پر وہ گوشت کا ٹکڑا پاتے ہیں اور جب وہ لید کے پاس سے گذرتے ہیں اس پر وہ خوراک پاتے ہیں۔‘‘","",{"k":"رزین۔"}],[505,"رویفع رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: میرے بعد شاید تجھے زندگی لمبی ملے فرمایا لوگوں کو خبر دے دو کہ جس نے داڑھی کو گرہ لگائی یا گلے میں حلقہ ڈالا یا چوپائے کی لید سے یا ہڈی سے استنجا کیا تو محمد صلی اللہ علیہ وسلم اس سے بری ہیں۔","",{"k":"ابوداود (36)۔ نسائی (5067)۔ احمد (16552)۔ صحیح، البانی: 27۔","m":"سَتَطُولُ سین مستقبل کے لیے ہے، مضارع معلوم واحد مذکر، دراز ہوگی۔ فَأَخْبِرْ افعال سے امر حاضر، بتا دینا۔ تَقَلَّدَ تفعل سے ماضی واحد مذکر غائب، لٹکائی۔ وَتَرٌ تندی دھاگا۔","e":"۱۔ ان کا نام ونسب یہ ہے، رویفع بن ثابت بن سکن بن عدی بن حارثہ انصاری مدنی رضی اللہ عنہ صحابی ہیں۔\nہیں۔ مصر میں رہائش پذیر تھے۔ ۴۶ ہجری میں سیدنا معاویہ رضی اللہ عنہ نے انہیں طرابلس پر امیر مقرر کیا، انہوں نے افریقہ میں جہاد کیا، رقہ میں ۵۶ ہجری میں وفات پائی۔ (تقریب) ۲۔ یہ واقعتاً دراز عمر ہوئے تھے، یہ افریقہ میں فوت ہونے والوں میں سے آخری صحابی ہیں۔ ۳۔ مقصد یہ ہے کہ جب تم درازی عمر سے نوازے جاؤ گے تو تم دیکھو گے لوگ علانیہ نافرمانیوں کا ارتکاب کر رہے ہیں تو انہیں بتانا کہ فلاں فلاں کام نافرمانی ہے، اس سے بچو۔ ۴۔ اس حدیث میں پہلی مذکور بات یہ ہے کہ داڑھی گھنی کرنے کے لیے یا تکبر سے داڑھی کو گرہیں باندھ لیتے تھے۔ اسے برا کام قرار دے کر اس سے منع کر دیا گیا ہے۔ آج کل لوگ داڑھی لپیٹ لپیٹ کر ہاتھوں میں کچھا سا بنا کر اکٹھی کرتے رہتے ہیں اس سے بھی اجتناب کرنا چاہیے۔ ۵۔ پہلے لوگ کمان کی تندی لے کر گھوڑے وغیرہ سواریوں کے گلے میں ڈال دیتے تھے۔ یا پھر اس تندی سے گھنٹی باندھتے تھے، اس طرح جانور کے تیز رفتار چلنے کی صورت میں اس کا گلا گھٹنے کا خطرہ تھا، اس لیے آپ صلی اللہ علیہ وسلم نے تندی باندھنے سے روکا ہے، اس کے علاوہ یہ تندی لے کر اپنے بچوں، گھوڑوں کے گلوں میں تعویذ ڈالتے تھے اور ان کا ذہن یہ تھا اس طرح نظر بد نہیں لگتی اور آفات سے یہ تندی بچاتی ہے اس وجہ سے منع کیا گیا ہے۔ بچانے والا تو اللہ ہے، یہ تندی کیا کرے گی۔ آخر میں لید اور ہڈی سے استنجاء کی ممانعت ہے، یہ تفصیلاً اوپر گزر چکا ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے سخت زجر و توبیخ کرتے ہوئے یہ جاہلی کام کرنے والے سے اعلان براءت کر دیا ہے۔"}],[506,"سیدنا عمر رضی اللہ عنہ سے مروی ہے کہ انہوں نے پیشاب کیا اور اپنے ذکر کو مٹی سے صاف کیا پھر ہم لوگوں کی طرف متوجہ ہو کر کہا: ہمیں اسی طرح تعلیم دی گئی ہے۔ (اوسط بسند ضعیف)","",{"k":"طبرانی اوسط، اس میں روح بن جناح راوی ہے، جو ضعیف ہے۔ ہیثمی: 1052۔"}],[507,"عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول کریم صلی اللہ علیہ وسلم نے فرمایا: ’’دس امور فطرت سے ہیں مونچھیں کاٹنا، داڑھی بڑھانا، مسواک کرنا، ناک میں پانی ڈالنا، ناخن تراشنا، انگلیوں کے پوروں کو دھونا، بغلوں کے بال اکھاڑنا، زیر ناف کے بال منڈوانا، اور استنجا کرنا۔ مصعب بن شبیہ نے کہا میں دسواں کام بھول گیا مگر یہ کہ وہ کلی کرنا ہو گا۔ وکیع رحمہ اللہ نے کہا انتقاص الماء سے مراد استنجا ہے۔‘‘","",{"k":"مسلم (261)۔ کتاب الطہارة، ترمذی (2757)۔ نسائی (5042)۔ ابوداود (53)۔ ابن ماجہ (293)۔ احمد (24539)۔","m":"عَشْرٌ دس خصائل، یہ مبتداء ہے۔ مِنَ الْفِطْرَةِ یہ خبر ہے یعنی فطرت سے ہیں، یعنی پرانا طریقہ ہے، انبیائے کرام نے انہیں اختیار کر رکھا تھا۔ قَصُّ کاٹنا۔ الشَّارِبِ اوپر والے ہونٹ پر اگنے والے بال۔ إِعْفَاءُ افعال سے مصدر ہے۔ اَللَّحْيَةِ داڑھی، یعنی وہ بال جو رخساروں اور ٹھوڑی پر ہوتے ہیں۔ اِسْتِنْشَاقُ استفعال سے مصدر ہے، ناک میں پانی داخل کرنا۔ اَلْبَرَاجِمِ اس کا واحد بُرْجُمَةٌ ہے، انگلیوں کے جوڑ۔ نَتْفِ اکھاڑنا۔ اَلْعَانَةِ زیر ناف۔","e":"۱۔ انہیں بالکل مونڈنا بھی جائز ہے، اور کاٹنا بھی جائز ہے کہ منہ میں نہ آئیں اوپر والا ہونٹ نظر آئے۔ ۲۔ بعض نے کہا ہے کہ داڑھی طول و عرض سے کاٹ کر اس کی خراش تراش کر سکتے ہیں لیکن نبی صلی اللہ علیہ وسلم کا فرمان اس کے برعکس ہے کہ داڑھی پوری رکھی جائے اور اسے اپنی حالت پر چھوڑ دیا جائے۔ ۳۔ مسواک وہ لکڑی ہے جسے دانتوں پر پھیرا جائے، یہ ہر لکڑی سے جائز ہے مگر جھاؤ کی ہو تو زیادہ بہتر ہے۔ (التشخیص: ۱/۲۶) یہ تمام اوقات میں کی جاسکتی ہے لیکن وضو اور نماز سے پہلے اس کی بہت تاکید ہے مسواک والی نماز کو بغیر مسواک والی نماز پر ستر گنا افضل قرار دیا گیا ہے۔ (احمد) ۴۔ ناک میں میل کچیل پھنس جاتی ہے، اس لیے اچھی طرح اسے پانی سے صاف کیا جائے اور پھر جھاڑا جائے، خصوصاً وضو کے وقت یا نیند سے بیدار ہوکر، ناک میں پانی ڈالا جائے۔ ۵۔ اگر ناخن زیادہ بڑے ہوں تو طہارت میں انگلیوں تک پانی پہنچنا مشکل ہو جاتا ہے اور میل کچیل بھی جمع ہو جاتی ہے جس سے کراہت آتی ہے، اس لیے بڑھے ہوئے ناخن کاٹنے کا حکم ہے۔ ۶۔ انگلیوں کے جوڑوں میں میل بیٹھ جاتی ہے اس لیے انہیں خصوصی دھونے کی ترغیب ہے۔ ۷۔ بغلوں میں مکروہ بخارات اٹھتے ہیں اس لیے زیر بغل بالوں کو مونڈنے کا حکم ہے اصل تو یہی ہے کہ ان بالوں کو اکھاڑ دیا جائے۔ اگر تکلیف ہو پھر تنگی نہ اختیار کی جائے انہیں مونڈھ دیا جائے یا پاؤڈر کے ذریعے زائل کر دیا جائے مقصد تو صفائی ہے جیسے بھی ممکن ہو۔ ۸۔ زیر ناف بالوں میں قبل و دبر پر آنے والے بال ہیں اور ان کے اردگرد والے بال بھی مونڈھے جا سکتے ہیں یہ استرے، پاؤڈر یا کریم وغیرہ سے کسی بھی طرح صاف کیے جا سکتے ہیں اور مرد و زن دونوں جس چیز کے ذریعے چاہیں صاف کر سکتے ہیں یہ جو مشہور ہے کہ عورت لوہا استعمال نہیں کر سکتی یہ بے اصل بات ہے جس چیز کے ساتھ چاہیں صفائی کر سکتے ہیں۔ ۹۔ استنجاء کا ذکر ہے، تفصیل اوپر آچکی ہے۔ ۱۰۔ مصعب بن شیبہ راوی کہتے ہیں، یہ مذکورہ نو اشیاء ہیں، دسویں میں بھول گیا ہوں۔ پھر یاد آیا تو بتایا، وہ کلی کرنا ہے۔ بعض روایات میں پانچ چیزوں کو فطرت میں سے قرار دیا گیا ہے، یہاں دس ہیں تو اس میں تعارض نہیں پہلے آپ کو پانچ کا علم تھا بعد میں دس کا علم ہوا جیسے آپ کو علم ہوا ویسا ہی بتاتے گئے۔ (مرعاۃ: ۱/۴۴۳)"}],[508,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کیا میں تمہیں خبر دوں اس چیز کی جس کی وجہ سے اللہ تعالیٰ خطائیں مٹا دے اور درجات بلند کر دے؟ لوگوں نے عرض کی: ہاں اے اللہ کے رسول! فرمایا: نا پسند کرتے ہوئے مکمل وضو کرنا، مساجد کی طرف بکثرت قدم بقدم چلنا، نماز پڑھنے کے بعد دوسری نماز کے انتظار میں رہنا پس یہ ہے سرحد مضبوط کرنا، تین بار فرمایا۔","",{"k":"مسلم (251)۔ کتاب الطہارۃ، ترمذی (51)۔ نسائی (143)۔ احمد (9361)۔ مالک: 386۔","m":"أَلَا ہمزہ استفہام ہے، لَا نفی ہے تو أَلَا یہ تنبیہ کے لیے ہے۔ أَدُلُّكُمْ، نَصَرَ سے مضارع معلوم واحد متکلم ضمیر مفعول بہ ہے، میں تمہیں بتاؤں گا۔ عَلَى مَا وہ چیز۔ يَمْحُو مضارع معلوم واحد مذکر غائب، مٹاتا ہے۔ إِسْبَاغُ افعال سے مصدر ہے پورا اور کامل وضو کرنا۔ اَلْمَكَارِهِ اس کا واحد مَكْرَهٌ ہے، مشقت۔ اَلْخُطَا اس کا واحد خُطْوَةٌ ہے، دو قدموں کے درمیان فاصلہ، مراد قدم ہیں۔ اَلرِّبَاطُ اس کا اصل معنی ہے دشمن کے خلاف سرحد کی حفاظت کے لیے وہاں بیٹھے رہنا۔","e":"۱۔ ارشاد ربانی ہے:\n﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ ﴾ [المائدة: ۶]\n’’اے لوگو جو ایمان لائے ہو! جب تم نماز کی طرف کھڑے ہوں تو اپنے چہروں اور ہاتھوں کو کہنیوں سمیت دھو لو، اور اپنے سروں کا مسح کرو اور پاؤں بھی ٹخنوں سمیت دھوؤ۔‘‘ درج ذیل احادیث میں اسی حکم ربانی کی تفصیلات ہیں۔ ۲۔ وضو واؤ پر فتح ہو تو اس پانی کو کہتے ہیں جس سے وضو کیا جائے۔ وضوء واؤ پر ضمہ ہو تو وضو کے فعل کو کہتے ہیں، آدمی آداب وضو اور اس کے مسنون طریقے برقرار رکھتے ہوئے جو وضو کا عمل کرتا ہے، اسے وضو کہتے ہیں۔ ۳۔ نبی اکرم صلی اللہ علیہ وسلم نے سوالیہ انداز سے مسئلہ سمجھایا ہے، کیونکہ اس طرح بات بہت جلد دل میں اترتی ہے۔ ۴۔ جو گناہ کراماً کاتبین نے لکھے ہوتے ہیں اور حقوق العباد نہیں تو اللہ تعالیٰ انہیں مٹا دیتا ہے۔ حقوق العباد تو تب ہی معاف ہوتے ہیں اگر حق والا معاف کرے حقوق اللہ اور صغیرہ گناہ وضو سے معاف ہو جاتے ہیں کبیرہ توبہ کے بغیر معاف نہیں ہوتے اور اس وضو سے جنت میں اور دنیا میں بلند مقام حاصل ہوتا ہے۔ ۵۔ مشقتوں پر وضو کی صورت یہ ہے کہ ٹھنڈے پانی سے وضو کیا، جسمانی تکلیف ہو پھر بھی وضو کیا، دنیاوی امور سے مشغولیت ہٹا کر یہ کارِ خیر کیا، پانی نہ ملنے کی صورت میں اسے تلاش کیا۔ ۶۔ درجات کی بلندی کے لیے ایک یہ نیک کام کہ وضو پورا کیا جائے، (۲) مساجد کی جانب زیادہ قدم اٹھائے جائیں وہ یا تو گھر سے دور والی مسجد میں جانا ہے، یا بار بار جانا بھی ہو سکتا ہے، اور قدموں کو چھوٹا چھوٹا کر کے مسجد کی جانب چلنا ہے۔ (۳) مسجدوں میں بیٹھ کر نماز کا انتظار کرنا، گھر میں مصروفیت کے باوجود یا کاروبار میں مگن رہنے کے باوجود نماز کی تیاری رکھنا اور اس کا اہتمام کرنا اور نماز سے دلی وابستگی رکھنا، یہ کام کرنے سے جس طرح اسلام کی خاطر سرحدوں کے تحفظ کے لیے گھوڑے باندھنے کا ثواب ہے ان سے وہ ثواب حاصل ہوتا ہے، جو ایک مجاہد گھڑ سوار کو ہوتا ہے جو ہمہ وقت اسلام کی سربلندی کے لیے کمر بستہ ہے، اسے اس کی اہمیت کے پیش نظر نبی اکرم صلی اللہ علیہ وسلم نے تکرار سے رباط قرار دیا ہے اور انہی لوگوں پر اللہ تعالیٰ کا یہ فرمان صادق آتا ہے:\n﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا ﴾ [آل عمران: ۲۰۰]\n’’اے لوگو جو ایمان لائے ہو! صبر کرو، اور آپس میں صبر کی تلقین کرو اور سرحدوں پر گھوڑے باندھو۔‘‘\nاس کی ایک تفسیر یہی ہے کہ مسجدوں میں نمازوں کا انتظار کرو۔ سرحدوں پر گھوڑے باندھنے سے اسلام کو دشمنوں سے بچانا ہوتا ہے، یہ مذکورہ بالا کام سرانجام دینے سے بھی شیطانی راہوں کو روکا جاتا ہے، نفس کو شہوات سے قابو میں رکھا جاتا ہے، اس لیے ان کاموں کو رباط قرار دیا گیا ہے۔"}],[509,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب مسلمان یا مومن بندہ وضو کرتا ہے اور چہرہ دھوتا ہے تو اس کے چہرے کے وہ گناہ جو آنکھوں سے دیکھنے سے کیے تھے وہ پانی کے ساتھ یا پانی کے آخری قطرے کے ساتھ خارج ہو جاتے ہیں۔ اور جب وہ ہاتھ دھوتا ہے تو خارج ہو جاتے ہیں اس کے ہاتھ کے تمام گناہ جو ہاتھ سے پکڑ کر کیے جاتے تھے پانی کے ساتھ یا آخری قطرے کے ساتھ۔ اور جب وہ پاؤں دھوتا ہے تو وہ تمام گناہ جن کی طرف پاؤں سے چل کر گیا تھا پانی کے ساتھ یا پانی کے آخری قطرے کے ساتھ خارج ہو جاتے ہیں۔ یہاں تک کہ بالکل گناہوں سے صاف ہوکر نکل جاتا ہے۔‘‘","",{"k":"مسلم (244)۔ کتاب الطہارۃ، ترمذی (2)۔ احمد (7960)۔ مالک: 63۔ دارمی (718)۔","m":"الْمُسْلِمُ، أَوِ الْمُؤْمِنُ یہ مترادف المعنی ہیں، مگر یہاں راوی کو شک ہے، اس لیے اس نے دونوں لفظ بیان کر دیے۔ إِلَيْهَا ضمیر خطیئہ کی جانب ہے، اس نے خطا کو دیکھا۔ مَعَ الْمَاءِ أَوْ آخِرِ قَطْرِ الْمَاءِ یہاں بھی راوی کو شک ہے۔ اس سے حدیث کی صحت پر اثر نہیں پڑتا، بلکہ اس کے تحفظ کا پتہ چلتا ہے، یعنی ادھر پانی کا قطرہ جدا ہوتا ہے تو ادھر گناہ مٹتے ہیں۔ بَطَشَتْهَا، ضَرَبَ سے ماضی معلوم واحد مؤنث غائب، ضمیر مفعول بہ ہے، جو خطیئہ (گناہ) کی جانب لوٹتی ہے، پکڑا اس گناہ کو۔ مَشَتْهَا، ضَرَبَ سے ماضی واحد مؤنث غائب ہے، ضمیر مفعول بہ ہے، خطیئہ کی جانب لوٹتی ہے، اس گناہ کی طرف ٹانگ اٹھی ہے اور چلی ہے۔ نَقِيًّا، تَقِيَ يَنْقِي سے اسم صفت ہے، حال ہونے کی وجہ سے منصوب ہے، صاف ہوکر۔","e":"آنکھ سے غلط کام دیکھنا، حرام چیزوں پر نظر ڈالنا اور ہاتھ سے غیر محرم کو چھونا، یا گناہ کی چیز تحریر کرنا اور پاؤں سے کسی گناہ کے کام کے لیے قصداً چل کر جانا۔ الغرض تمام اعضاء سے سرزد ہونے والے گناہ وضو کے قطرات گرنے سے گر جاتے ہیں۔ علامہ عبید اللہ رحمانی رحمہ اللہ فرماتے ہیں: جَمِيعُ الذُّنُوبِ مِنَ الصَّغَائِرِ (مرعاة: ۱/۳۶۹) ’’صغیرہ تمام گناہ گرتے ہیں، کبیرہ تو توبہ سے معاف ہوتے ہیں۔‘‘"}],[510,"سیدنا عقبہ بن عامر رضی اللہ عنہ سے مروی ہے کہ ہمارے ذمہ اونٹ چرانا تھا۔ جب میری چرانے کی نوبت آئی تو میں چرا کے شام کو واپس لایا تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو کھڑے ہو کر لوگوں سے خطاب کرتے پایا۔ میں آپ صلی اللہ علیہ وسلم کے ارشاد میں سے یہ سن پایا: جب کوئی مسلمان اچھی طرح وضو بنائے اور پھر نماز کے لیے کھڑا ہو کر دو رکعت ادا کرے اپنے دل اور منہ سے نماز پر متوجہ رہے تو اس کے لیے جنت واجب ہو جاتی ہے۔ میں نے کہا یہ تو بہت عمدہ عمل ہے۔ میرے آگے جو آدمی تھا اس نے کہا: جو اس سے پہلے بیان فرمایا ہے وہ اس سے بھی زیادہ عمدہ تھا۔ میں نے دیکھا تو وہ عمر بن خطاب رضی اللہ عنہ تھے۔ انہوں نے فرمایا: میرا خیال ہے تو ابھی ابھی آیا ہے۔ آپ صلی اللہ علیہ وسلم نے پہلے فرمایا ہے: تم میں سے جو شخص اچھی طرح وضو بنائے اور مکمل وضو بنائے اور پھر وہ کہے: ’’میں گواہی دیتا ہوں کہ کوئی عبادت کے لائق مگر اللہ، وہ ایک ہے، اس کا کوئی شریک نہیں ہے اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اللہ کے بندے اور اس کے رسول ہیں تو اس کے لیے جنت کے آٹھوں دروازے کھل جاتے ہیں وہ جس سے چاہے داخل ہو گا۔‘‘ (مسلم، ونسائی)","",{"k":"مسلم (234)۔ کتاب الطہارۃ، ترمذی (55)۔ نسائی (151)۔ ابوداؤد (906)۔ ابن ماجہ (1770)۔ احمد (16995)۔","m":"رِعَايَةُ اونٹ چرانا۔ نَوْبَتِي میری باری۔ فَرَوَّحْتُهَا تفعیل سے ماضی واحد مذکر متکلم، میں ان اونٹوں کو دوپہر کے بعد واپس لایا۔ مُقْبِلًا افعال سے اسم فاعل ہے، حال ہونے کی وجہ سے منصوب ہے، پوری توجہ کے ساتھ۔ عَلَيْهِمَا ان دونوں رکعات پر۔ مَا أَجْوَدَ فعل تعجب ہے، کتنا عمدہ ہے۔","e":"اس حدیث میں اچھا وضو کرنے کے بعد نماز پڑھنے کی فضیلت بیان ہوئی ہے، اگر وضو کے بعد کسی نماز کا وقت ہو وہ پڑھ لی جائے تو بھی یہی ثواب ہے۔ اگر کسی نماز کا وقت نہیں تو وضو کی دو رکعات پڑھی جائیں تو یہ ثواب حاصل ہوگا۔ اور اچھے وضو سے مراد یہ ہے کہ اعضائے وضو خشک نہ رہ جائیں اور سنت کے مطابق اس کے تمام طریقے استعمال کیے جائیں۔ دل اور چہرے کے ساتھ نماز پڑھے، یعنی دل غافل نہ ہو، اور چہرہ ادھر ادھر نہ جھانکے، مقصد ہے کہ مکمل خشوع اور خضوع سے پڑھے، خشوع کا تعلق دل سے ہے اور خضوع کا تعلق اعضاء سے ہے۔ اور باقی جو خوشخبری ہے، اچھا وضو کرنے کے بعد جنت کی بشارت کی، اصل تو جنت میں ایمان کے ساتھ جانا ہے، ایمان ہوگا تو جنت میں داخلہ ہے، اگر ایمان نہیں تو جنت میں داخلہ نہ ہو گا۔ مراد ہے ایمان ہو اور مسنون وضو کرے اور نماز پڑھے یکسوئی کے ساتھ تو پھر حسن خاتمہ کی علامت ہے، یہ اول دفعہ ہی بغیر رکاوٹ جنت میں داخل ہوگا۔ ۲۔ اس میں وضو کے بعد کی دعا بیان کی گئی ہے، اور اس کا ثواب بتایا گیا ہے وضو کے بعد اس دعا میں اشارہ ہے کہ یہ وضو کا عمل خالص اللہ کے لیے ہے، جس طرح ظاہری گندگی سے وضو کے ذریعے طہارت ہوتی ہے، اسی طرح شرک اور ریا کاری سے دل صاف ہو جاتا ہے۔ ۳۔ جنت کے آٹھوں دروازے اس عمل کی تعظیم کے پیش نظر کھولے جائیں گے، وگرنہ داخلہ تو ایک ہی سے ہو گا، اس سے مقصد لوگوں کے سامنے اس عمل کے کرنے والے کی شرافت بیان کرنا ہے۔ جو نیکی انسان زیادہ کرے گا اسی دروازے سے اس کا جنت میں داخلہ ہو گا۔ ہر دروازہ سے اجازت اس آؤ بھگت کے لیے ہے۔ اس حدیث میں جنت کے دروازوں کی تعداد کا تعین بھی ثابت ہوا کہ وہ آٹھ ہیں۔"}],[511,"ابوداؤد کی روایت میں ہے: میں نے کہا بس بس۔ یہ تو کتنا بہتر عمل ہے اور اس میں یہ بھی ہے کہ اچھی طرح وضو کر کے پھر اپنی نگاہ آسمان کی طرف اٹھائے۔","",{"k":"ابوداود (169)۔ البانی رحمہ اللہ نے اسے صحیح قرار دیا ہے، مگر علامہ شمس الحق رحمہ اللہ نے کہا: وفی اسناده رجل مجهول عون المعبود: 1/66۔ اس کی سند میں مجہول راوی ہے، اس نظر اٹھانے والے اضافہ کے بغیر یہ دعا والی حدیث کو مسلم (234)۔ نسائی (151)۔ احمد (16942)۔ دارمی (716)۔ نے بھی بیان کیا ہے۔","m":"بَخْ بَخْ خاء پر جزم سے بھی پڑھتے ہیں، خاء پر تشدید بھی دیتے ہیں، کسی چیز کی تعریف کرتے ہوئے، کسی چیز کی پسندیدگی پر کہا جاتا ہے۔ واہ واہ کے معنی میں ہے۔","e":"اس میں وضو کے بعد نگاہ آسمان کی جانب اٹھا کر دعا کرنے کا ذکر ہے۔ مگر یہ صحیح طریقہ سے ثابت نہیں۔ صرف دعا ہی پڑھی جائے نظر یا ساتھ انگلی کا اشارہ ثابت نہیں۔"}],[512,"اور ترمذی نے مزید یہ نقل کیا ہے کہ کہے: ’’اللہ کر دے مجھے توبہ کرنے والوں سے اور کر دے مجھے طہارت کرنے والوں سے۔‘‘","",{"k":"ترمذی (55)۔ نسائی (148)۔ ابن ماجہ (470)۔ محدثین میں سے بعض نے اس کی صحت پر اعتراض کیا ہے اور کہا ہے کہ یہ مضطرب ہے۔ (مرعاۃ: 1/373) لیکن البانی رحمہ اللہ نے کہا، صحیح ہے: 48۔","m":"اجْعَلْنِي فعل امر واحد مذکر حاضر نون وقایہ، یاء مفعول بہ، مجھے کر دے۔","e":"یعنی مذکورہ بالا وضو کے بعد والی دعا پڑھنے کے بعد اسے بھی پڑھیں۔ یہ اس آیہ مبارکہ کی تعبیر ہے: ﴿إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ﴾ (البقرة: ۲۲۲) ’’یقیناً اللہ تعالیٰ توبہ کرنے والوں اور پاک رہنے والوں کو پسند کرتے ہیں۔‘‘ توبہ سے باطن کی طہارت گناہوں کے دور ہونے سے حاصل ہوتی ہے اور وضو سے ظاہر کی طہارت حاصل ہوتی ہے، یہ دونوں ظاہری اور باطنی پلیدگی قرب الٰہی میں رکاوٹ ہیں، اس لیے یہ دعا مناسبت رکھتی ہے کہ اے میرے اللہ تیرے قرب میں رکاوٹ بننے والی میل کچیل سے مجھے پاک کر دے تاکہ میں تیرا قرب حاصل کر سکوں۔"}],[513,"سیدنا عثمان بن عفان رضی اللہ عنہ نے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے اچھی طرح وضو کیا تو اس کی تمام خطائیں اس کے بدن سے خارج ہو جاتی ہیں یہاں تک کہ اس کے ناخنوں کے نیچے سے بھی خارج ہو جاتی ہیں۔‘‘","",{"k":"مسلم (245)، کتاب الطهارۃ، احمد (474)۔"}],[514,"ایک اور روایت میں ہے کہ انہوں نے وضو کیا اور پھر کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اسی طرح وضو کرتے دیکھا ہے جیسا میں نے یہ وضو کیا ہے اور پھر فرمایا: جس نے اس طرح وضو کیا اس کے سابقہ گناہ معاف کر دیے جائیں گے اور اس کی نماز اور اس کا مسجد جانا اس کی زائد عبادت ہو گی۔","",{"k":"مسلم (229)، کتاب الطهارۃ، بخاری (160)، نسائی (84)، ابوداود (106)، ابن ماجہ (285)، احمد (402)، مالک: 61، دارمی (693)۔","m":"نَافِلَةً یہ کان کی خبر ہے، زائد ہے، اضافہ ہے۔","e":"اس حدیث میں وضو کا یہ ثواب بیان ہوا ہے کہ وضو سے پہلے تمام گناہ معاف ہو جاتے ہیں اور نماز پڑھنے کے لیے چلنا اور پھر نماز پڑھنا اس کے علاوہ ثواب ہے، وہ درجات کی بلندی کا باعث ہوں گے، گناہ تو پہلے معاف ہو جاتے ہیں۔ لیکن یہ شرط ہے کہ نماز پوری توجہ سے پڑھی جائے اور وضو نبی اکرم صلی اللہ علیہ وسلم کی مانند ہو۔ جس کی وضاحت اس حدیث کے ایک حصہ میں بیان ہوئی ہے کہ ہاتھوں کو تین مرتبہ دھوئے، کلی کرے، ناک جھاڑے، تین مرتبہ چہرہ دھوئے، کہنیوں سمیت بازو دھوئے۔ سر کا مسح کرے جہاں سے شروع کیا وہیں پر ہاتھ پھر لوٹائے، پھر ٹخنوں سمیت پاؤں دھوئے، اس طرح تسلی بخش وضو کرے تو حدیث میں مذکور اعزاز ملے گا۔"}],[515,"سیدنا عثمان رضی اللہ عنہ وضو کے بعد ہنس دیئے اور پھر اپنے رفقاء کو کہا: تم مجھ سے پوچھتے نہیں ہو کہ میں کیوں ہنسا ہوں؟ تو لوگوں نے کہا: اے امیر المومنین! آپ کیوں ہنسے۔ انہوں نے کہا: میں نے دیکھا رسول اللہ صلی اللہ علیہ وسلم نے وضو کیا جیسا میں نے وضو کیا ہے اور آپ صلی اللہ علیہ وسلم ہنسے اور فرمایا: تم پوچھتے نہیں ہو کہ میں کیوں ہنسا ہوں تو لوگوں نے عرض کی یا رسول اللہ صلی اللہ علیہ وسلم! آپ صلی اللہ علیہ وسلم کو کس چیز نے ہنسایا ہے؟ فرمایا: جب بندہ وضو کا پانی منگواتا ہے اس بعد ذکر کیا مثل حدیث سابقہ کے۔","",{"k":"احمد (417)، و ابویعلی ورجالہ ثقات، فی الصحیح باختصار، ہیثمی: 1133۔","m":"الْبُقْعَةِ زمین کا ٹکڑا۔","e":"یعنی جو ثواب (۵۱۴) میں بیان ہوا ہے، وہ ثواب بیان کیا۔"}],[516,"سیدنا عبد اللہ صنابحی رضی اللہ عنہ بیان کرتے ہیں کہ رسول کریم صلی اللہ علیہ وسلم نے فرمایا: جب مومن بندہ وضو کرتا ہے اور منہ میں پانی ڈالتا ہے تو اس کے منہ کے تمام گناہ خارج ہو جاتے ہیں۔ اور جب ناک میں پانی ڈالتا ہے تو اس کی ناک کے تمام گناہ خارج ہو جاتے ہیں اور جب چہرہ دھوتا ہے تو اس کے چہرے کے تمام گناہ خارج ہو جاتے ہیں یہاں تک کہ آنکھوں کے اطراف سے نکل جاتے ہیں۔ جب ہاتھ دھوتا ہے تو تمام خطائیں اس کے دونوں ہاتھوں سے نکل جاتی ہیں یہاں تک کہ ہاتھوں کے ناخنوں سے گناہ نکل جاتے ہیں اور جب سر کا مسح کرتا ہے تو دو کانوں سے ہر گناہ نکل جاتا ہے۔ جب وہ پاؤں دھوتا ہے تو اس کے دونوں پاؤں سے یہاں تک کہ دو پاؤں کے ناخنوں کے نیچے سے گناہ خارج ہو جاتے ہیں اور پھر اس کا مسجد کو جانا اور نماز پڑھنا زائد عمل قرار پاتا ہے۔‘‘","",{"k":"نسائی (103)، ابن ماجہ (282)، احمد (18589)، مالک: 62، صحیح، البانی: 100۔","m":"فِيهِ جری حالت ہے، منہ سے۔ اسْتَنْثَرَ استفعال سے ماضی واحد مذکر غائب ہے، جھاڑا اس نے۔ أَشْفَارِ اس کا واحد شُفْرٌ ہے، پلکوں کی وہ جگہ جہاں بال اگتے ہیں۔"}],[517,"سیدنا ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: جس نے وضو پر وضو کیا تو اللہ تعالیٰ اس کے بدلے دس نیکیاں عطا کرتا ہے۔‘‘ (ترمذی)","",{"k":"ترمذی (59)، ابوداود (62)، ابن ماجہ (512)، ضعیف، البانی: 11۔"}],[518,"سیدنا ابوسعید رضی اللہ عنہ نے مرفوع حدیث بیان کی کہ رسول کریم صلی اللہ علیہ وسلم نے فرمایا: جس نے وضو کیا اور کہا: پاک ہے تو اللہ اور تیری حمد وثنا ہے، میں تجھ سے مغفرت طلب کرتا ہوں اور تیری طرف تائب ہوتا ہوں۔ تو ان کلمات کو ایک کتاب میں لکھا جاتا اور اس پر مہر ثبت کی جاتی ہے اور پھر عرش کے نیچے اٹھا کر رکھ دی جاتی ہے اور اس مہر کو تا قیامت توڑا نہیں جاتا۔‘‘ (رزین)","",{"k":"رزین۔"}],[519,"سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے سورت الکہف پڑھی اس کے لیے قیامت کے دن تک نور پھیلا ہوگا اور جس نے اس کی آخری دس آیات تلاوت کیں اور دجال خارج ہوا تو اس کو اس کے فتنے کا کوئی خطرہ نہ ہوگا اور جس نے وضو کرنے کے بعد کہا: پاک ہے تو اے اللہ! اور تیری تعریف ہے، تیرے سوا کوئی عبادت کے لائق نہیں تو ہی معبود ہے تجھ سے مغفرت طلب کرتا اور تیری طرف رجوع کرتا ہوں تو یہ کلمات ایک کتاب میں لکھ کر اس پر مہر لگائی جاتی ہے اور پھر اس کو قیامت سے پہلے نہیں کھولا جاتا۔‘‘","",{"k":"طبرانی اوسط: 1478۔"}],[520,"امام نسائی رحمہ اللہ نے اپنی ایک کتاب الیوم واللیلۃ میں اس حدیث کی تخریج کرنے کے بعد کہا ہے اس کو مرفوع کرنا غلطی ہے درست یہ ہے کہ موقوف ہے۔ پھر انہوں نے اس کو روایت کیا ہے ثوری اور غندر سے وہ شعبہ سے موقوف نقل کرتے ہیں۔‘‘","",{"k":"نسائی فی الیوم واللیلۃ، صحیح یہ ہے کہ یہ موقوف ہے، مرفوع غلط ہے۔"}],[521,"سیدنا ابوامامہ رضی اللہ عنہ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا جس نے مکمل وضو کیا، پھر فرض نماز کے لیے اٹھ کر چلا تو بخشا جاتا ہے اس کے لیے ہر وہ گناہ جس کی طرف اس کے پاؤں چلے، جس کو اس کے ہاتھوں نے پکڑا، جس کو اس کے کانوں نے سنا اور جس کو اس کی آنکھوں نے دیکھا اور جو اس کے نفس نے بدی کا خیال کیا۔‘‘","",{"k":"احمد (21769)، ونحوہ طبرانی کبیر، وفیہ ابو مسلم اس کے حالات کا پتہ نہیں۔ ہیثمی: 1125۔"}],[522,"ایک روایت میں یہ بھی ہے کہ کہا گیا: اے ابوامامہ! یہ بھی بتاؤ کہ اگر وہ کھڑا ہوا اور نماز پڑھی تو یہ اس کے لیے زائد اور نفل ہو گی؟ انہوں نے کہا نہیں: نفل تو رسول اللہ صلی اللہ علیہ وسلم کے لیے ہیں۔ دوسرے کے لیے نفل و زائد کیسے ممکن ہیں جب وہ گناہوں میں ڈور رہا ہے اس کے لیے تو فضیلت اور اجر ہے۔","",{"k":"احمد (21692)، ورواہ الطبرانی ورجالہ موثقون، ہیثمی: 1131۔","e":"انتباہ: اوپر صحیح احادیث میں ان احادیث کا مفہوم گزر چکا ہے۔"}],[523,"سیدنا عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے: ’’دو مرد میری امت میں سے ہیں ایک ان میں سے رات کو اٹھتا ہے اور اپنے نفس کا مقابلہ کرتا ہے اور وضو بناتا ہے۔ اس پر گرہ ہوتی ہیں۔ جب وضو کرتے وقت ہاتھ دھوئے تو ہاتھوں کی گرہ کھل جاتی ہے۔ جب منہ دھویا تو منہ کی گرہ کھل جاتی ہے۔ جب سر کا مسح کیا تو اس کی گرہ کھل جاتی ہے اور جب پاؤں دھوئے تو آخری گرہ کھل جاتی ہے۔ پس رب تعالیٰ فرماتا ہے: میرے بندے کو دیکھو! اپنے نفس کا خود مقابلہ کرتا ہے۔ میرا بندہ جو کچھ طلب کرے گا وہ کچھ اسی کا ہے۔‘‘ (یہ دونوں روایات مسند احمد اور الکبیر کی ہیں)","",{"k":"احمد (17004)، طبرانی کبیر، ولہ سندان عندھما رجالہ احدھما ثقات، ہیثمی: 1135۔"}],[524,"عبد خیر نے کہا: ہمارے پاس علی رضی اللہ عنہ آئے وہ نماز پڑھ چکے تھے اور انہوں نے وضو کے لیے پانی طلب کیا تو ہم نے کہا اب پانی کا کیا کریں گے نماز تو پڑھ چکے ہیں جو ان کو پڑھنا تھی مگر وہ ہمیں تعلیم دینا چاہتے ہوں گے۔ ایک برتن لایا گیا اور اس میں پانی تھا اور ایک تشتری بھی لائی گئی تو برتن سے دائیں ہاتھ پر پانی ڈال کر دونوں ہاتھ تین بار دھوئے۔ پھر منہ اور ناک میں تین بار اسی ہاتھ سے پانی ڈالا جس میں پانی لیا تھا مضمضہ کیا اور ناک صاف کیا۔ پھر بایاں ہاتھ تین بار دھویا۔ پھر برتن میں ہاتھ ڈالا اور سر کا مسح ایک ہی بار کیا۔ پھر دایاں پاؤں تین بار دھویا اور بایاں پاؤں تین بار دھویا۔ پھر کہا: جس کو رسول اللہ صلی اللہ علیہ وسلم کا وضو جاننا پسند ہو تو وہ یہ وضو ہے۔","",{"k":"ترمذی (48)، نسائی (115)، احمد (1383)، دارمی (701)۔ صحیح البانی: 102۔","m":"آتَانَا ماضی واحد مذکر غائب، ضمیر مفعول بہ ہمارے پاس آئے۔ مَا يُرِيدُ افعال سے مضارع منفی معلوم واحد مذکر غائب، نہیں ارادہ کیا۔ فَأُتِيَ ماضی مجہول واحد مذکر غائب لایا گیا۔ سَرَّهُ، نَصَرَ سے ماضی واحد مذکر جسے اچھی لگے، ضمیر مفعول یہ لفظ مَنْ کی جانب لوٹتی ہے۔","e":"انتباہ: اگرچہ حدیث قابل تسلی طریقہ سے ثابت نہیں ہو سکی، مگر اس کے مفہوم کی احادیث اوپر گزر چکی ہیں، ان میں اعضاء کے عقدہ (گرہیں) کھلنے کا مطلب یہی ہے کہ شیطان کے اثرات سے یہ اعضاء وضو محفوظ رہتے ہیں اور ان کے گناہ ختم ہو جاتے ہیں اور دعاء قبول ہوتی ہے یہ اوپر صحیح احادیث سے بھی ثابت ہو چکا ہے۔ اس حدیث کے مطلب کی وہ احادیث تائید کرتی ہیں۔\n۱۔ اس حدیث میں مسنون وضو کا مکمل طریقہ مذکور ہے۔ ۲۔ اس سے یہ بھی ثابت ہوا کہ صحابہ کرام رضی اللہ عنہم احکام دین کی تعلیم کا اہتمام فرماتے تھے، اور وضو کی اہمیت کا بھی پتہ چلتا ہے کہ یہ کوئی معمولی فریضہ نہ تھا۔ بلکہ اسے عبادت میں بنیادی حیثیت حاصل ہے۔ ۳۔ ثابت ہوا کہ صحابہ کرام رضی اللہ عنہم نے عمل میں لا کر حدیث کو محفوظ رکھتے تھے، یہ وہ طریقہ ہے جس سے حدیث ہمیشہ یاد ہو جاتی ہے، بھولتی نہیں۔"}],[525,"ان ہی کی روایت میں ہے: پس دائیں ہاتھ سے برتن پکڑا اور اپنے بائیں ہاتھ پر پانی ڈالا اور ہتھیلیاں تین بار دھوئیں۔ (اس کی مثل)","",{"k":"صحیح البانی: 103۔","m":"فَأَفْرَغَ افعال سے ماضی واحد مذکر غائب، ڈالا۔","e":"اس میں مسنون وضو میں یہ اضافہ ہے کہ وضو کا آغاز دائیں ہاتھ سے کیا جائے۔"}],[526,"ان روایات میں یہ بھی ہے: پھر منہ اور ناک کے لیے ایک ہی بار لیا گیا پانی ڈالا۔","",{"k":"ابوداؤد (111)، ترمذی (48)، نسائی (115)، احمد (1383)، دارمی (1701)، صحیح، البانی: 104۔","m":"الْاِسْتِنْشَاقُ استفعال سے مصدر ہے، ناک میں پانی داخل کرنا۔","e":"اس سے ثابت ہوا کہ کلی سے پانی بچا کر ناک میں داخل کیا جاتا تھا یعنی ایک ہی ہتھیلی سے کلی اور ناک میں پانی داخل کیا جائے۔\nابوداؤد، کتاب الطہارہ، باب فی الفرق بین المضمضۃ والاستنشاق میں حدیث آتی ہے، جس سے کلی کے لیے علیحدہ اور ناک کے لیے علیحدہ پانی لینے کا ذکر ہے مگر یہ حجت کے قابل نہیں ضعیف ہے۔ لیکن علامہ شمس الحق رحمہ اللہ فرماتے ہیں: وَمَحْصَلُ الْكَلَامِ إِنَّ الْوَصْلَ وَالْفَصْلَ كِلَاهُمَا ثَابِتٌ لَكِنْ أَحَادِيثُ الْوَصْلِ قَوِيَّةٌ مِنْ جِهَةِ الْإِسْنَادِ. (عون المعبود: ۵۳/۱) ’’حاصل گفتگو یہ ہے کہ کلی اور ناک میں ایک ہی ہاتھ سے بغیر نیا پانی لیے ملانا اور دونوں ناک اور کلی کے لیے علیحدہ پانی لینا دونوں طرح آپ صلی اللہ علیہ وسلم سے ثابت ہے، لیکن ملا کر یعنی ایک ہی پانی سے بغیر نیا پانی لیے کلی کرنے اور ناک میں پانی داخل کرنے والی احادیث سند کے لحاظ سے قوی ہیں۔ فاصلہ والی ثابت تو ہیں لیکن ان کی بہ نسبت کم قوت رکھتی ہے۔‘‘ یعنی نیا پانی لینا یا اسی پانی سے کلی کرنا اور ناک میں پانی داخل کرنا دونوں طرح جائز ہے۔ زیادہ مضبوط موقف دونوں کو ملانے کا ہی ہے، تاہم اگر کوئی علیحدہ پانی لیتا ہے تو جائز کام کرتا ہے غلط نہیں کرتا۔"}],[527,"ان میں سے ایک یہ ہے ابن عباس رضی اللہ عنہ نے کہا: میرے ہاں علی بن ابی طالب رضی اللہ عنہ تشریف لائے اور پہلے ہی باوضو تھے۔ پھر پانی طلب کیا مثل اس کے۔ اور اس میں ہے کہ پھر مضمضہ کیا اور ناک صاف کیا پھر دونوں ہاتھ ملا کر برتن میں داخل کیے اور ان میں پانی لیا اور منہ پر ڈالا پھر اپنے انگوٹھے اپنے کانوں پر اور اگلے حصے پر پھیر دیے۔ پھر دوسری اور پھر تیسری بار بھی ایسا ہی کیا، پھر تھوڑا سا پانی لے کر اپنی پیشانی پر بہا کر چھوڑ دیا اور چہرے پر بہتا چلا گیا۔ پھر دونوں کلائیاں دھوئیں کہنیوں سمیت تین بار پھر سر کا اور کانوں کی پشت کا مسح کیا۔ اس کے بعد دونوں ہاتھ ملا کر کانوں میں ڈالے اور پانی لے کر نعلین پہنے ہوئے پاؤں کو بھی اسی طرح دھویا۔ میں نے کہا: کیا نعلین میں دھوئے ہیں تو انہوں نے کہا: نعلین میں۔ تین بار کہا۔","",{"k":"ابوداؤد (117)، ترمذی (48)، نسائی (115)، احمد (1383)، دارمی (701)، حسن، البانی: 108۔","m":"عَلَيَّ ضمیر متکلم مجرور یاء مشدد، میرے پاس داخل ہوئے۔ إِهْرَاقَ افعال سے ماضی واحد مذکر غائب، یہ اصل میں أَرَاقَ تھا۔ اس میں ھاء کا اضافہ کر دیا گیا ہے، پانی بہایا، مراد ہے پیشاب کیا۔ بِوَضُوءٍ واؤ پر فتحہ ہے، وضو کا پانی۔ حَفْنَةٌ اس کی جمع حَفْنَاتٌ ہے، چلو بھر کر، یا لپ۔ أَلْقَمَ افعال سے ماضی واحد مذکر غائب، لقمہ بنایا۔ إِبْهَامَيْهِ اپنے دونوں انگوٹھوں کے ساتھ۔ یعنی دونوں کانوں میں انگوٹھوں کو لقمہ کی مانند بنا لیا۔ کانوں کو انگوٹھے سے پکڑا اور دھویا۔ الثَّانِيَةَ وَالثَّالِثَةَ یہ محذوف فعل کی وجہ سے منصوب ہے، یعنی وہ چلو پہلی دفعہ کے بعد دوسری دفعہ مارا، پھر تیسری دفعہ مارا۔ اتنی مرتبہ بھی کانوں میں انگلیاں پھیریں۔ قَبْضَةٌ مٹھی بھر پانی، یہ مفعول بہ ہے۔ فَصَبَّهَا فاء پس ماضی واحد مذکر غائب ضمیر مفعول بہ وہ مٹھی بھر پانی ڈالا۔ فَتَرَكَهَا پس، ماضی واحد مذکر غائب ضمیر مفعول بہ ہے، وہ مٹھی بھر پانی چھوڑ دیا۔ تَسْتَنُّ افتعال سے مضارع معلوم واحد مؤنث غائب، وہ بہتا ہے۔ فَتَلَهَا یہ ضَرَبَ سے ماضی واحد مذکر غائب ہے، ضمیر رِجْلٌ (پاؤں) کی جانب لوٹتی ہے، اسے ملا، اس کا اصل معنی ہوتا ہے۔ مڑوڑا۔ الْأُخْرَى دوسرا پاؤں بھی۔","e":"۱۔ اس حدیث میں بھی مسنون وضو کا مکمل طریقہ ہے۔ ۲۔ ثابت ہوا کہ وضو کرتے ہوئے چہرے پر زور سے پانی مارنا جائز ہے۔ ۳۔ چہرے کے ساتھ ہی کانوں کا اگلا حصہ چہرے کو دھوتے ہوئے دھویا جائے۔ ۴۔ چہرہ دھونے کے بعد جتنی دفعہ چہرہ دھویا جائے اتنی دفعہ ہی پیشانی پر پانی مارنا مستحب ہے۔ ۵۔ اس حدیث کے آخر سے یہ شبہہ ہوتا ہے کہ پاؤں جوتے سمیت مل کر دھوئے تھے اور بعض نے یہ دلیل پکڑی ہے کہ پاؤں پر مسح کیا تھا، دھویا نہ تھا۔ مگر یہ غلط ہے کیونکہ مسح کا لفظ صرف چیز پر ہاتھ پھیرنے کے معنی میں بھی آتا ہے اور دھونے کے معنی میں بھی آتا ہے، یہاں لفظ فَتَلَهَا آیا ہے، جس کا معنی دھونا ہے، کیونکہ بعض نسخوں میں غَسَلَهَا پاؤں دھونے کے لفظ ہیں، ثابت ہوا دھونا مراد ہے۔ (عون المعبود: ۴۴/۱) باقی رہی بات جوتے سمیت پاؤں دھونا یہ کیسے ممکن ہے، تو یہ ممکن ہے کہ جوتا چپل نما ہو اور ہاتھ سے مل کر پاؤں دھو لیے جائیں۔"}],[528,"سیدنا حسین بن علی رضی اللہ عنہ سے روایت ہے مثل اس کے اور اس میں یہ بھی ہے کہ پھر کھڑے ہو کر وضو کا بقیہ پانی پی لیا تو مجھے کہا: تعجب نہ کر میں نے تیرے باپ محمد صلی اللہ علیہ وسلم کو ایسا ہی کرتے دیکھا ہے جیسا تو نے مجھے کرتے دیکھا۔‘‘","",{"k":"نسائی (95)، ترمذی (48)، ابوداؤد (117)، احمد (1383)، دارمی (701)، صحیح، البانی: 93۔","m":"فَقَرَّبْتُهُ تفعیل سے ماضی واحد متکلم، ضمیر مفعول بہ، جو وضو کے پانی کی جانب لوٹتی ہے، میں نے وہ وضو کا پانی قریب کیا۔ قَائِمًا یہ حال ہے، اس حال میں کہ کھڑے ہوئے۔ نَاوِلْنِي مفاعلہ سے امر واحد مذکر حاضر نون وقایہ یاء مفعول بہ ہے۔ مجھے پکڑاؤ۔ فَعَجِبْتُ، عَلِمَ سے ماضی واحد متکلم، میں نے تعجب کیا۔ وَشُرْبِ پیتے، یہ لِوُضُوئِهِ پر عطف ہے، اس لیے مجرور ہے، یعنی وضو کے بارے میں کہا اور وضو کے بچے ہوئے پانی کے بارے میں کہا۔","e":"۱۔ اس حدیث میں بھی مسنون وضو کا بیان ہے۔ ۲۔ مزید یہ بیان ہوا ہے کہ وضو کرنے کے بعد اگر برتن میں بچا پانی ہو تو اسے پینا مستحب ہے۔ ۳۔ عادت چونکہ بیٹھ کر پانی پینے کی تھی، سیدنا علی رضی اللہ عنہ نے جب کھڑے ہو کر پانی پیا تو بیٹے نے تعجب کیا، انہیں یہ بتا کر ان کا تعجب دور کیا کہ نبی اکرم صلی اللہ علیہ وسلم نے ایسے کیا تھا، اس لیے میں نے بھی کھڑے ہو کر پانی پیا ہے۔ اس بارے میں فیصلہ کن بات یہ ہے کہ جن احادیث میں کھڑے ہو کر پانی پینے کی ممانعت ہے، وہ تنزیہی طور پر (احتیاطی) ہے، اور یہ حدیث کھڑے ہو کر پانی پینا جائز قرار دے رہی ہے تو اس سے جواز ملتا ہے، عادت بیٹھ کر ہی پینے کی ہو۔ بوقت ضرورت کھڑے ہو کر پینے کی اجازت ہے۔ (تعلیقات سلفیہ: ۱/ ۱۵، حاشیہ: ۲۱)"}],[529,"عبداللہ بن زید سے روایت ہے کہ انہوں نے برتن سے اپنے ہاتھوں پر پانی بہایا اور انہیں دھویا، پھر منہ میں اور ناک میں ایک چلو سے تین بار پانی ڈالا۔‘‘","",{"k":"بخاری (191)، مسلم (235)، ترمذی (32)، نسائی (98)، ابوداؤد (188)، ابن ماجہ (434)، احمد (16024)، مالک: 32، دارمی (694)۔","m":"كَفَّةٌ ایک تھیلی۔"}],[530,"سیدنا عثمان رضی اللہ عنہ کے غلام حمران نے کہا کہ عثمان رضی اللہ عنہ نے برتن منگوایا اور اپنے ہاتھوں پر پانی ڈالا اور دونوں ہاتھ تین مرتبہ دھوئے پھر دایاں ہاتھ برتن میں ڈالا اور منہ اور ناک میں پانی ڈالا۔ پھر چہرے کو تین بار دھویا اور ہاتھوں کو کہنیوں تک تین بار دھویا، پھر سر کا مسح کیا، پھر پاؤں ٹخنوں سمیت تین بار دھویا اور پھر کہا: میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم نے میرے اس وضو کی مثل وضو کیا اور پھر آپ صلی اللہ علیہ وسلم نے فرمایا: جس نے اس طرح وضو کیا جیسا میں نے کیا ہے اور پھر دو رکعات نماز پڑھی اور دل میں باتیں نہ کیں تو اس کے سابقہ گناہ معاف کر دیئے جائیں گے۔‘‘ (بخاری و مسلم)","",{"k":"بخاری (160)، مسلم (229)، نسائی (84)، ابوداؤد (110)، ابن ماجہ (285)، احمد (554)، دارمی (693)۔"}],[531,"ابوداؤد کی روایت میں ہے انھوں نے کہ سر کا مسح تین بار کیا۔","",{"k":"ابوداؤد (110)، حسن، صحیح، البانی: 101، بخاری (160)، مسلم (230)، نسائی (116)، ابن ماجہ (285)، احمد (491)، مالک: 61، دارمی (693)۔","e":"سر کا مسح ایک مرتبہ ہی ہے، تین مرتبہ مسح کرنے والی روایات اس کے مقابل نہیں آسکتیں لہذا سر کا مسح ایک مرتبہ ہی ہے۔ (عون المعبود: ۱/ ۴۱) اگر تین مرتبہ مسح کرنے والی حدیث صحیح بھی ہو تو اس کا مطلب ہے، شروع سے سر سے ہاتھ گدی تک لے گئے، اور پھر گدی سے جہاں شروع کیا تھا وہاں لے گئے اور بال خراب ہو جاتے تھے، انہیں درست کرتے تو انہیں تین مرتبہ سے تعبیر کیا گیا ہے۔ حالانکہ یہ ایک بار ہی مسح بنتا ہے۔"}],[532,"ابن ابی ملیکہ سے وضو کے بارے میں سوال کیا گیا اس نے کہا میں نے عثمان بن عفان رضی اللہ عنہ کو دیکھا ان سے وضو کے بارے میں سوال کیا گیا۔ انھوں نے وضو کا برتن منگوایا اور پانی کو اپنے دائیں ہاتھ پر ڈالا پھر اس کو پانی میں داخل کیا، تین بار کلی کی اور تین بار ناک صاف کیا اور اس میں ہے کہ سر اور کانوں کا مسح کیا، کانوں کے اندر اور باہر سے ایک بار دھوئے۔","",{"k":"ابوداؤد (108)۔ حسن، صحیح، البانی: 99، 100۔ بخاری (160)۔ مسلم (230)۔ ابن ماجہ (285)۔ نسائی (116)۔ احمد (491)۔ مالك: 61۔ دارمی (693)۔","m":"أَتِيَ ماضی مجہول واحد مذکر غائب، لایا گیا۔ بِمِيضَأَةٍ وہ برتن جس میں وضو کا پانی سما جائے۔ فَأَصْغَاهَا افتعال سے ماضی واحد مذکر غائب، ضمیر مفعول بہ ہے، برتن کی جانب لوٹتی ہے، اسے انڈیلا، مائل کیا۔"}],[533,"دوسری ایک روایت میں ہے: دائیں ہاتھ سے بائیں ہاتھ پر پانی ڈال کر ان دونوں کو ہاتھوں کے بند (گٹ) تک دھویا۔","",{"k":"ابوداؤد (108)۔ حسن، صحیح، البانی: 99، 100۔ بخاری (160)۔ مسلم (230)۔ ابن ماجہ (285)۔ نسائی (116)۔ احمد (491)۔ مالك: 61۔ دارمی (693)۔","m":"الْكُوعَيْنِ ہاتھ کے جوڑ، مراد گٹ یعنی گٹوں تک ہاتھ دھوتے۔"}],[534,"عبد اللہ بن زید بن عاصم انصاری رضی اللہ عنہ سے مروی ہے مثل اس کے اور اس میں یہ بھی ہے کہ سر کا مسح کیا اور آگے سے دونوں ہاتھوں کو لے گئے اور پیچھے سے لوٹا کر لے آئے۔ سر کے اگلے حصے سے مسح کرنے کی ابتداء کی اور پھر ان دونوں کو گردن تک لے گئے پھر واپس کر کے وہاں لے آئے جہاں سے ابتدا کی تھی۔","",{"k":"بخاری (185)۔ مسلم (235)۔ ترمذی (32)۔ نسائی (98)۔ ابوداؤد (118)۔ ابن ماجہ (434)۔ احمد (16024)۔ مالك: 32۔ دارمی (694)۔","m":"فَأَقْبَلَ افعال سے ماضی واحد مذکر غائب، آگے سے شروع کیا۔ بِهِمَا ان دونوں ہاتھوں کو۔ وَأَدْبَرَ افعال سے ماضی واحد مذکر غائب، پیچھے گدی کی طرف لے جانا۔ قَفَاهُ اپنی گدی۔","e":"۱۔ دونوں ہاتھوں کے ساتھ مسح سے یہ واضح ہوتا ہے کہ آپ صلی اللہ علیہ وسلم نے پورے سر کا مسح کیا تھا، بعض حصے کا نہیں کیا تھا۔ اس لیے سارے سر کا مسح کرنا ہو گا۔ اور اس میں سر کے مسح کا طریقہ بیان ہوا ہے کہ سر کے اگلے حصے سے شروع کیا جائے اور ہاتھوں کو گدی تک لے جائیں پھر جہاں سے شروع کیا تھا اسی جگہ ہاتھوں کو واپس لے آئیں۔ ۲۔ پاؤں کو مطلق دھونے کا آیا ہے، علامہ عبید اللہ رحمہ اللہ بخاری کے حوالے سے اضافہ کرتے ہیں کہ پاؤں ٹخنوں سمیت دھوتے ہیں۔ (مرعاۃ: ۱/ ۴۵۵)"}],[535,"اور ایک روایت میں ہے کہ وضو کیا دو دو بار۔","",{"k":"نسائی (97)۔ صحیح، البانی: 95۔ بخاری (199)۔ مسلم (236)۔ ترمذی (47)۔ ابوداؤد (120)۔ ابن ماجہ (434)۔ احمد (16017)۔ مالك: 32۔ دارمی (694)۔","m":"مَرَّتَيْنِ اس کا واحد مَرَّةٌ ہے، یہ تثنیہ ہے، دو مرتبہ۔","e":"اس سے ثابت ہوتا ہے کہ وضو کے اعضاء دو دو مرتبہ بھی دھوئے جا سکتے ہیں یہ جائز ہے۔"}],[536,"اور ایک روایت میں ہے کہ منہ اور ناک میں ایک ہتھیلی سے پانی ڈالا گیا اور تین بار ایسا کیا۔","",{"k":"مسلم (235)۔ كتاب الطهارة، بخاری (199)۔ نسائی (98)۔ ترمذی (35)۔ ابوداؤد (120)۔ ابن ماجہ (434)۔ احمد (16037)۔ مالك: 32۔ دارمی (709)۔"}],[537,"ایک روایت میں ہے کہ دونوں ہاتھوں پر باقی ماندہ تری کے ساتھ سر کا مسح کیا۔","",{"k":"مسلم، كتاب الطهارة: 235۔","m":"غَبَرَ جو باقی بچا۔"}],[538,"اور ایک روایت میں ہے کہ دونوں ہاتھوں پر باقی ماندہ پانی کے علاوہ پانی لے کر اس کے ساتھ سر کا مسح کیا۔‘‘ (امام ترمذی نے کہا یہ اصح روایت ہے)","",{"k":"ترمذی (35)۔ وقال هذا اصح، صحیح، البانی: 32۔ بخاری (199)۔ مسلم (236)۔ نسائی (98)۔ ابوداؤد (120)۔ ابن ماجہ (434)۔ احمد (16037)۔ مالك: 32۔ دارمی (709)۔","m":"غَيْرِ فَضْلِ یہ مضاف الیہ ہے، فضل آگے مضاف ہے، مطلب ہے اپنے ہاتھوں کے بقیہ پانی سے نہیں بلکہ اس کے علاوہ نیا پانی لیا تھا۔","e":"اس سے ثابت ہوتا ہے کہ سر کے مسح کے لیے نیا پانی لیا جائے، علامہ عبید اللہ رحمانی رحمہ اللہ فرماتے ہیں: «كِلَا الْأَمْرَيْنِ جَائِزَانِ وَإِنْ شَاءَ أَخَذَ لِرَأْسِهِ مَاءً أَجْدِيرًا وَإِنْ شَاءَ مَسَحَهُ بِفَضْلِ مَاءٍ يَكُونُ فِي يَدِهِ» (مرعاۃ: ۱/ ۴۷۸) ’’دونوں کام جائز ہیں، اگر چاہے تو سر کے مسح کے لیے نیا پانی لے اور اگر چاہے تو ہاتھوں میں بچے ہوئے پانی سے سر کا مسح کرے۔‘‘"}],[539,"دوسری ایک روایت ہے کہ منہ تین بار دھویا ہاتھ دو دو بار اور پاؤں بھی دو دو بار دھوئے اور سر کا مسح بھی دو بار کیا۔","",{"k":"ترمذی (47)۔ صحیح الاسناد، اس میں پاؤں دھونے کے بارے میں جو مرتین کا لفظ ہے یہ شاذ ہے۔ البانی: 43۔ اس کے علاوہ اوپر 538 والی تخریج ہے۔","e":"اس سے ثابت ہوا کچھ اعضاء تین مرتبہ کچھ دو مرتبہ ہر طرح اعضائے وضو دھونا جائز ہے۔"}],[540,"مقدام بن معدی کرب کی روایت میں مثل اس کے ہے اور اس میں یہ بھی ہے راوی نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا مسح کیا دونوں کانوں کے ظاہر کا اور اندرونی حصے کا اور اپنی انگلی دونوں کانوں کے سوراخ میں ڈالی۔","",{"k":"ابوداؤد (122)۔ ابن ماجہ (442)۔ احمد (16737)۔ 1۔ صحیح، البانی: 114۔","m":"صِمَاخ کانوں کے سوراخ جو دماغ تک جاتے ہیں۔","e":"اس میں کانوں میں انگلیوں کو پھیرنے کا طریقہ بتایا گیا ہے کہ انگوٹھے اوپر پھیرے جائیں اور انگلیاں کانوں میں جو گڑھے ہیں، ان میں پھیری جائیں اس طرح مکمل کانوں کا مسح ہو جاتا ہے۔"}],[541,"ابو عبداللہ سالم بن سبلان رضی اللہ عنہ سے روایت ہے کہ ام المومنین عائشہ رضی اللہ عنہا نے اس کو دکھایا کہ نبی کریم صلی اللہ علیہ وسلم کیسے وضو کرتے تھے اس روایت میں ہے کہ ام المومنین نے ایک ہی بار سر کا مسح کیا اور صرف پیچھے کو ہاتھ لے گئیں اور پھر دونوں ہاتھ اپنے دو کانوں پر پھیر دیئے، پھر دو رخساروں پر پھیر دیئے۔ سالم رضی اللہ عنہ کہتے ہیں میں ام المومنین کی خدمت میں حاضر ہوتا رہا جب تک میں مکاتب تھا تو ام المومنین میرے سامنے بیٹھی ہوتی تھیں اور مجھ سے بات چیت کرتی تھیں۔ پھر ایک دن میں ان کے پاس گیا اور میں نے کہا: میرے لیے برکت کی دعا کیجیے تو انہوں نے کہا: وہ کیا ہے؟ میں نے کہا: اللہ تعالیٰ نے مجھے آزاد کر دیا ہے تو انہوں نے کہا اللہ تعالیٰ تیرے لیے برکت کر دے اور انہوں نے اسی وقت میرے سامنے پردہ لٹکا دیا اور اس دن کے بعد ام المومنین کو میں نے نہیں دیکھا۔","",{"k":"نسائی (100)۔ صحیح الاسناد، البانی: 97۔","m":"تَسْتَعْجِبُ استفعال سے مضارع معلوم واحد مؤنث غائب، پسند کرتی تھی۔ وَتَسْتَأْجِرُهُ استفعال سے مضارع معلوم واحد مؤنث غائب، اجرت پر رکھتی تھیں۔ فَأَرَتْنِي افعال سے واحد مؤنث ماضی غائب نون وقایہ یاء مفعول بہ، مجھے دکھایا۔ أَمَرَّتْ افعال سے واحد مؤنث غائب، گزارا۔ مُكَاتَبًا مفاعلہ سے اسم مفعول، قسط سے آزاد ہونے والا غلام۔ تَخْتَفِي افتعال سے واحد مؤنث غائب، مضارع معلوم مخفی نہ ہوتی تھیں۔ وَأَرْخَتِ افعال سے ماضی واحد مؤنث غائب، لٹکا دیا۔","e":"۱۔ اس میں مکمل وضو کا طریقہ بیان ہوا ہے۔ ۲۔ قسط سے آزاد ہونے والا غلام (مکاتب) جب تک اس پر ایک قسط بھی باقی ہے، وہ غلام ہے اور اگر غلام تمام قسطیں ادا کر دیتا ہے تو وہ آزاد ہو جاتا ہے، غلام سے پردہ نہیں، آزاد ہو جائے تو پھر اس سے پردہ ہے۔ ۳۔ نیک انسان سے دعائے برکت کرانی چاہیے۔ ۴۔ ام المومنین سیدہ عائشہ رضی اللہ عنہا شریعت کی سخت پابند تھیں۔"}],[542,"عمرو بن شعیب نے اپنے باپ سے اس نے اس کے دادا سے روایت کی ہے کہ ایک اعرابی نے آ کر نبی کریم صلی اللہ علیہ وسلم سے وضو کا مسئلہ پوچھا پس آپ صلی اللہ علیہ وسلم نے اس کو تین تین بار اعضاء کو دھو کر دکھایا اور پھر فرمایا وضو اس طرح ہے جس نے اس سے زیادہ کیا اس نے غلط کیا، زیادتی کی اور ظلم کیا۔‘‘ (ابوداؤد اور نسائی نے الفاظ موخر الذکر کے ہیں)","",{"k":"نسائی (140)۔ ابوداؤد (135)۔ ابن ماجہ (422)۔ حسن، صحیح، البانی: 136۔","m":"فَأَرَاهُ افعال سے ماضی واحد مذکر غائب، ضمیر مفعول بہ ہے، اعرابی کی طرف لوٹتی ہے، اسے نبی صلی اللہ علیہ وسلم نے وضو دکھایا۔ أَسَاءَ افعال سے ماضی واحد مذکر غائب، آداب شرع کی رعایت نہ رکھی برا کیا۔ تَعَدَّى تفعل سے ماضی واحد مذکر غائب، حد سے تجاوز کیا۔ ظَلَمَ، ضرب سے ماضی واحد مذکر غائب، تین سے زیادہ کر کے خود پر ظلم کیا کہ جان کو تھکا دیا۔","e":"۱۔ یہ اعرابی سائل کی حیثیت سے آیا ہے اور نبی اکرم صلی اللہ علیہ وسلم سے وضو کی کیفیت پوچھتا ہے، چونکہ کسی چیز کی زبانی تعلیم کی یہ نسبت فعلی اور عملی طور پر تعلیم و تربیت کرنا زیادہ مؤثر ہے اس لیے آپ صلی اللہ علیہ وسلم نے اسے عملاً وضو دکھانا چاہا تا کہ مؤثر ہو۔ ۲۔ یہاں جو وضو کرنے کا ذکر کرتے ہوئے تین تین مرتبہ اعضاء دھونے کا آیا ہے، یہاں سے سر کا مسح تین مرتبہ کرنے کا نہ سمجھ لیا جائے، سر کا مسح ایک ہی مرتبہ۔ ۳۔ وضو کے شرع نے جو آداب بتائے ہیں، ان کا خیال نہ رکھنا گویا کامل شریعت کو نقص والی قرار دینا ہے، اسے اساء (برا) قرار دیا گیا ہے۔ کسی چیز کو تکمیل کی حد قرار دیا جائے اس سے آگے گزرنے کو تعدّی کہتے ہیں۔ تین سے زیادہ بار اعضاء دھونے کو آگے تجاوز کرنے والا قرار دیا ہے کیونکہ یہ وضو کی مقررہ باری کی حد سے آگے گزر گیا ہے۔ پانی ضائع کرنے اور تین بار سے تجاوز کر کے حصول ثواب سے زائد کام کیا ہے، اس لیے اسے ظلم سے تعبیر کیا گیا ہے، البتہ اعضائے وضو زیادہ دھونے یعنی پاؤں یا بازو اوپر تک دھو لیں یہ جائز ہے، تعداد تین سے اضافہ منع ہے۔ ان کلمات کے اظہار سے سخت قسم کا انکار کیا گیا ہے اور ڈانٹ دی گئی ہے کہ تین بار سے تجاوز کرنے والا سخت برا کام کرتا ہے۔ (مرعاۃ: ۱/ ۴۸۱)"}],[543,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تمام اعضاء کو ایک ایک بار دھو کر وضو کیا اور اس پر زیادہ نہ کیا۔‘‘ (بخاری)","",{"k":"بخاری (157)۔ ترمذی (42)۔ نسائی (102)۔ ابوداؤد (138)۔ ابن ماجہ (439)۔ احمد (3440)۔ دارمی (697)۔","m":"تَوَضَّأَ تفعل سے ماضی واحد مذکر غائب، وضو کیا۔ مَرَّةً مفعول مطلق ہونے کی وجہ سے منصوب ہے۔","e":"اس سے ثابت ہوتا ہے کہ نبی صلی اللہ علیہ وسلم نے وضو کے ہر عضو کو ایک ایک مرتبہ بھی دھویا ہے، اگر یہ خشک نہ رہیں تو ایک مرتبہ بھی دھونا جائز ہے۔"}],[544,"عطاء بن یسار کہتے ہیں کہ ابن عباس رضی اللہ عنہ نے کہا: کیا تمہیں یہ پسند ہے کہ میں تمہیں دکھاؤں کہ رسول اللہ صلی اللہ علیہ وسلم وضو کیسے کیا کرتے تھے؟ پھر انہوں نے ایک برتن میں پانی طلب کیا اور دائیں ہاتھ میں پانی لے کر منہ اور ناک میں ڈالا، پھر دونوں ہاتھ ملا کر پانی لیا اور چہرہ دھویا، پھر پانی لے کر دایاں ہاتھ دھویا پھر پانی لیا اور اس کے ساتھ بایاں ہاتھ دھویا پھر مٹھی برابر پانی لے کر ہاتھ پر چھڑک دیا اور اس کے ساتھ سر اور کانوں کا مسح کیا، پھر ایک ہاتھ سے پانی لے کر دائیں پاؤں پر ڈالا اور دو ہاتھوں سے مل دیا ایک ہاتھ پاؤں پر اور دوسرا ہاتھ اس کے نیچے تھا پھر دوسرے پاؤں کو بھی اسی طرح دھویا۔‘‘","",{"k":"ابوداؤد (137)۔ بخاری (157)۔ ترمذی (42)۔ نسائی (102)۔ ابن ماجہ (439)۔ احمد (2412)۔ دارمی (697)۔ ابوداؤد والی حسن ہے۔ لیکن مسح القدم شاذ، البانی: 125۔","m":"ہمزہ استفہام۔ تُحِبُّونَ افعال سے مضارع معلوم جمع مذکر حاضر، کیا تم پسند کرتے ہو۔ أَنْ ناصبہ ہے یہ کہ أُرِيكُمْ افعال سے مضارع معلوم واحد متکلم، ضمیر مفعول بہ ہے، میں تمہیں دکھاؤں۔ فِيهِ اس برتن میں۔ فَاغْتَرَفَ افتعال سے ماضی واحد مذکر غائب، چلو بھرے۔ غُرْفَةٌ غین کے فتحہ کے ساتھ، معنی مصدر کا ہے، لپ بھرنا۔ أُخْرَى دوسری لپ بھری۔ بِهَا اس چلو کے ساتھ۔ فَرَشَّ، نَصَرَ سے ماضی واحد مذکر غائب، پانی ڈالا، چھڑکا۔","e":"۱۔ یہ بات ذہن نشین کر لیں کہ اعضائے وضو ایک ایک مرتبہ دھونے فرض ہیں اور تین مرتبہ دھونے سنت ہیں اور بعض احادیث صحیحہ سے دو دو مرتبہ دھونا بھی ثابت ہے اور کچھ اعضاء ایک مرتبہ کچھ اعضاء دو مرتبہ اور کچھ اعضاء تین مرتبہ دھونا یہ سب جائز ہے۔ (عون المعبود: ۱/ ۵۲) ۲۔ اور اس حدیث میں جو یہ آیا ہے کہ اپنے دائیں پاؤں پر پانی چھڑکا، اس سے مراد دھونا ہے اگر یہ مراد نہ ہو تو یہ قدم کا مسح کرنے والے الفاظ شاذ ہیں تو صحیح نہیں۔ کہ اتنا پانی پاؤں دائیں اور پھر بائیں پر چھڑکا کہ وہ بہنے لگا اور اس میں پاؤں دھونے کا طریقہ بھی بتایا گیا ہے کہ ایک ہاتھ پاؤں کے اوپر اور دوسرا ہاتھ پاؤں کے نیچے پھیر کر انہیں دھویا جائے۔"}],[545,"سیدہ ربیع بنت معوذ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے تھے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے وضو کا طریقہ بیان کیا: پس ہاتھوں کو تین بار دھویا، منہ تین بار دھویا، منہ اور ناک میں ایک ایک بار پانی ڈالا اور ہاتھوں کو تین تین بار دھویا اور سر کا مسح دوبار کیا۔ سر کے پچھلے حصے سے شروع کیا پھر اس اگلے حصے سے شروع کیا۔ دونوں کانوں کا مسح کیا ظاہر کا اندر کا اور پاؤں کو تین بار دھویا۔","",{"k":"ابوداؤد (126)۔ ترمذی (34)۔ ابن ماجہ (441)۔ احمد (26475)۔ دارمی (690)۔ حسن، البانی: 117۔","m":"فَحَدَّثَتْنَا تفعیل سے ماضی واحد مؤنث غائب، ربیع نے ہم سے یہ حدیث بیان کی۔ أَنَّهُ ضمیر نبی اکرم صلی اللہ علیہ وسلم کی جانب ہے۔ اُسْكُبِي، نَصَرَ سے امر واحد مؤنث حاضر، تو پانی ڈال۔ وَضُوءٌ وضو کا پانی۔ فَذَكَرَتْ ماضی واحد مؤنث غائب، ربیع نے ذکر کیا۔ وُضُوءٌ آپ کا وضو کرنا۔ فِيهِ اس وضو کے بارے میں کہا۔ وَضَّأَ تفعیل سے ماضی واحد مذکر غائب، دھویا۔","e":"اس حدیث میں جو یہ آیا ہے کہ آپ صلی اللہ علیہ وسلم نے سر کا مسح پچھلی جانب سے شروع کیا تھا، یہ راوی سے تحریف ہوئی ہے، اصل یہی ہے کہ آپ صلی اللہ علیہ وسلم نے مسح سر کے اگلے حصہ سے شروع کیا اور پیچھے لے گئے اور پھر جہاں سے شروع کیا تھا، اسی جگہ پر لوٹایا یا اگلے حصہ سر سے شروع کیا اور آخر تک لے گئے، یہ پچھلی جانب سے مسح شروع کرنے کا ثبوت درست نہیں۔ (عون المعبود: ۱/ ۴۸)"}],[546,"سیدہ ربیع بنت معوذ بن عفراء رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس کے ہاں وضو کیا: سارے سر کا مسح کیا بالوں کے اوپر ہر طرف سے اس انداز سے مسح کیا کہ بال اپنی حالت پر رہے بالوں کو حرکت نہیں دی۔‘‘","",{"k":"ابوداؤد (128)۔ ترمذی (34)۔ ابن ماجہ (441)۔ احمد (26475)۔ دارمی (690)۔ حسن، البانی: 118۔","m":"قَرْنٌ بالوں کے گچھے کو کہتے ہیں، سر کی کسی جانب بھی بال ہوں انہیں قَرْنٌ کہتے ہیں۔ نَاحِيَةٍ ہر جانب۔ لِمُنْصَبٍّ انفعال سے اسم مفعول ہے، گرنے کی جگہ۔ یعنی سر کا نچلا حصہ۔ هَيْئَتِهِ اس کی حالت۔","e":"اس حدیث میں دلالت ہے کہ سر کا مسح سر کے اگلے حصے سے شروع کیا جائے اور اسے پیچھے لے جائیں اور سر کی ہر جانب سے بالوں پر مسح کیا جائے مگر بال اپنی حالت سے تبدیل نہ ہوں، ان میں حرکت نہ ہو۔ یعنی پورے سر کا مسح کیا جائے۔"}],[547,"اور دوسری روایت میں ہے: سر کا مسح کیا اس کے اگلے حصے اور اس کے پچھلے حصے کا، دونوں کنپٹیوں کا، دونوں کانوں کا ایک ایک بار۔‘‘","",{"k":"ترمذی (34)۔ ابوداؤد (129)۔ ابن ماجہ (441)۔ احمد (26475)۔ حسن الاسناد، البانی: 31۔","m":"مَا أَقْبَلَ مِنْهُ جو اس سر کے آگے والا حصہ ہے۔ وَمَا أَدْبَرَ اور جو پیچھے والا ہے، یہ پہلے جو آیا ہے کہ سر کا مسح کیا اس کی تفسیر ہے یعنی سر کے اگلے حصہ سے شروع کیا اور آخر تک لے گئے، اور پھر پچھلے حصے سے ہاتھ اگلے حصے تک لے آئے۔ صُدْغَيْهِ یہ تثنیہ ہے نون اضافت کی وجہ سے گرا ہے، یہ آنکھ اور کان کے درمیان والی جگہ ہے۔ کنپٹی یعنی اس پر لٹکے ہوئے بالوں پر بھی مسح کیا۔ مَرَّةً وَاحِدَةً یہ پہلے سارے جملہ کی قید ہے یہ آگے پیچھے یا کنپٹی وغیرہ کے بالوں پر مسح اگر چہ دیکھنے میں دو مرتبہ لگتا ہے، مگر یہ ایک مسح ہے۔","e":"یہ حدیث دلالت کرتی ہے کہ کنپٹی اور کان کا مسح سر کے مسح کے ساتھ ایک ہی مرتبہ کرنا چاہیے، یہ طریقہ مسنون اور جائز ہے۔ باقی رہا دو مرتبہ تین مرتبہ سر کا مسح کرنے کے متعلق جو احادیث وارد ہیں ان میں تنقید ہے، سنداً درست نہیں، صحیح احادیث صرف ایک مرتبہ ہی مسح کرنے پر دلالت کرتی ہیں یا پھر ہاتھوں کو پھیرنے کو ایک ایک دفعہ قرار دیا گیا ہے مگر مسح ایک ہی مرتبہ ہے۔ (تحفۃ الاحوذی: ۱/ ۳۷)"}],[548,"ایک روایت میں ہے: سر کا مسح ہاتھوں پر باقی ماندہ پانی سے کیا۔","",{"k":"ترمذی (35)۔ صحیح، البانی: 32۔ بخاری (199)۔ مسلم (236)۔ نسائی (98)۔ ابوداؤد (120)۔ ابن ماجہ (434)۔ احمد (16037)۔ مالك: 32۔ دارمی (709)۔","m":"غَيْرِ ہاتھوں میں بچا تھا، اس کے علاوہ یعنی نیا پانی لیا، اس کی وضاحت حدیث نمبر ۵۳۸ میں گزر چکی ہے۔"}],[549,"طلحہ بن مصرف کے دادا سے منقول ہے کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو سر کے اگلے حصے سے ابتدا کر کے پچھلے حصہ کی طرف مسح کرتے دیکھا ہے یہاں تک کہ ہر دو ہاتھوں کو دو کانوں کے نیچے سے نکالا۔ مسدد نے کہا کہ میں نے یہ حدیث یحییٰ سے بیان کی تو انہوں نے اس کو منکر کہا۔","",{"k":"ابوداؤد (132)۔ ضعیف، البانی: 19۔ احمد (15521)۔"}],[550,"سیدنا ابوامامہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے وضو کیا اور فرمایا: دونوں کان سر سے ہیں۔ حماد نے کہا مجھے معلوم نہیں کہ یہ ابوامامہ رضی اللہ عنہ کا قول ہے یا نبی کریم صلی اللہ علیہ وسلم کا ارشاد ہے۔","",{"k":"ترمذی (37)۔ ابن ماجہ (444)۔ البانی صحیح: 34۔","m":"لَا أَدْرِي مضارع معلوم واحد متکلم، میں نہیں جانتا۔ هَذَا یہ اشارہ ہے، الْأُذُنَانِ مِنَ الرَّأْسِ کی طرف کہ کان سر میں سے ہیں۔","e":"یہ قول کہ کان بھی سر میں سے ہیں، بہت سارے ائمہ کا موقف ہے ان میں سے ابو حاتم، ابوزرعہ، دارقطنی، بہیقی بھی ہیں کہ یہ صحابی رضی اللہ عنہ کا قول ہے۔ مگر حافظ ابن حجر رحمہ اللہ فرماتے ہیں: وَالظَّاهِرُ أَنَّهُ مَرْفُوعٌ لَيْسَ بِمُدْرَجٍ وَالْحَدِيثُ حَسَنٌ أَوْ صَحِيحٌ. (التلخيص: ۱/ ۲۳)\n’’ظاہر ہے کہ یہ الفاظ مرفوع نبی صلی اللہ علیہ وسلم سے ثابت ہیں کسی راوی سے مدرج نہیں اور حدیث حسن یا صحیح ہے۔‘‘ اسی طرح علامہ زیلعی حنفی رحمہ اللہ نے بھی مرفوع ہی کہا ہے۔ (نصب الرایہ: ۱/ ۲۰) اس کا مطلب یہ ہے کہ کانوں کا مسح سر والے پانی سے کیا جائے چہرے والے پانی سے نہ کیا جائے، البتہ جب چہرہ دھوئیں تو کانوں کو ساتھ دھو لیں۔ پھر یہ مسئلہ حل طلب ہے کہ سر کے بعد کانوں پر جب مسح کریں اس کے لیے وہی پانی کافی ہے یا کہ نیا لیا جائے۔ تو ہم یہ پہلے وضاحت کر چکے ہیں کہ افضل یہی ہے کہ سر والے پانی کے ساتھ ہی کانوں کا مسح کیا جائے اگر نیا لیا جاتا ہے تو یہ بھی جائز ہے، کوئی حرج نہیں۔"}],[551,"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے ایک آدمی نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اس نے وضو کیا اور ناخن برابر جگہ دو قدموں پر خشک چھوڑ دی تھی تو اس کو نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’واپس جا کر اچھی طرح اپنا وضو کر۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (173)۔ احمد (12078)۔ صحیح، البانی: 158۔","m":"الظُّفْرِ اس کی جمع أَظْفَارٌ ہے، اور جمع الجمع أَظَافِيرُ ہے۔ ناخن۔ لَهُ اس اعرابی سے کہا۔ اِرْجِعْ، ضَرَبَ سے امر واحد مذکر، لوٹ جا۔ فَأَحْسِنْ افعال سے امر حاضر، اچھا کر۔ وُضُوءَكَ اپنا وضو۔"}],[552,"سیدنا جابر رضی اللہ عنہ سے اس کے مثل مروی ہے۔","",{"k":"مسلم (243)۔ كتاب الطهارة، ابوداؤد (173)۔ ابن ماجہ (666)۔ احمد (154)۔"}],[553,"خالد بن معدان سے مروی ہے جو بعض صحابہ رضی اللہ عنہم سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ایک مرد کو نماز پڑھتے دیکھا جس کے پاؤں پر درھم برابر جگہ خشک تھی جس کو پانی نہیں پہنچا تھا پس آپ صلی اللہ علیہ وسلم نے اس کو وضو اور نماز کا اعادہ کرنے کا حکم دیا۔","",{"k":"ابوداؤد (175)۔ احمد (15069)۔ صحیح، البانی: 161۔","m":"ظَهْرِ اوپر والا حصہ۔ لُمْعَةٌ ایک ٹکڑا، مراد ہے، پاؤں کے ایک حصہ پر خشکی تھی، اس کی تفسیر یہ ہے۔ لَمْ يُصِبْهَا افعال سے نفی جحد واحد مذکر ہے۔ ضمیر مفعول بہ ہے، جو قدم کی جانب لوٹتی ہے، اسے پانی نہ لگا تھا۔ فَأَمَرَهُ اس آدمی کو حکم دیا۔ أَنْ يُعِيدَ افعال سے مضارع معلوم واحد مذکر غائب أَنْ نے نصب دیا ہے، یہ کہ وہ لوٹائے۔","e":"رقم ۵۵۲۔ جو مسلم کے حوالہ سے اشارہ دیا گیا ہے، اس کے الفاظ یہ ہیں: عَنْ جَابِرٍ قَالَ أَخْبَرَنِي عُمَرُ بْنُ الْخَطَّابِ أَنَّ رَجُلًا تَوَضَّأَ فَتَرَكَ مَوْضِعَ ظُفْرٍ عَلَى قَدَمِهِ فَأَبْصَرَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ ارْجِعْ فَأَحْسِنْ وُضُوءَكَ فَرَجَعَ ثُمَّ صَلَّى. (مسلم، كتاب الطهارة، باب استيعاب جميع اجزاء محل الطهارة) سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ مجھے سیدنا عمر بن خطاب رضی اللہ عنہ نے بتایا کہ ایک آدمی نے وضو کیا اور اپنے قدم پر ایک ناخن کے برابر جگہ چھوڑ دی، یعنی خشک رہ گئی اسے نبی اکرم صلی اللہ علیہ وسلم نے دیکھا اور کہا: واپس لوٹ جا اور اپنا وضو اچھا کر، چنانچہ وہ لوٹا، وضو درست کیا اور پھر نماز پڑھی۔ ۲۔ اس سے ثابت ہوا کہ وضو کے اعضاء میں سے کوئی جگہ علم نہ ہونے کی وجہ سے بھی دھونے سے رہ جائے یا خشک رہ جائے تو وہ وضو درست نہیں دوبارہ وضو کیا جائے کیونکہ ایک روایت میں ہے۔ ثُمَّ تَوَضَّأَ (مسند احمد) ۳۔ انجان اور جاہل کو نرمی سے تعلیم دی جائے، سختی سے برے اثرات مرتب ہوتے ہیں۔ ۴۔ پاؤں میں موزے یا جرابیں ہوں تو مسح ٹھیک ہے۔ اگر یہ نہ ہوں تو اصل بات یہ ہے کہ وضو میں پاؤں دھوئے جائیں مسح نہ کیا جائے۔"}],[554,"سیدنا عبداللہ ابن عمرو بن العاص رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم سفر میں ہم لوگوں سے پیچھے چلے آتے تھے جب آپ صلی اللہ علیہ وسلم ہم تک پہنچ آئے تو نماز کا وقت قریب آ چکا تھا اور ہم لوگوں نے پاؤں پر تر ہاتھ سے مسح کرنا شروع کر دیا، پس آپ صلی اللہ علیہ وسلم نے بلند آواز سے فرمایا: ’’ایڑیوں کے لیے آگ کا عذاب ہو گا۔‘‘ دو یا تین بار فرمایا۔ (بخاری و مسلم)","",{"k":"بخاری (60)۔ مسلم (241)۔ نسائی (111)۔ ابوداؤد (97)۔ احمد (7063)۔","m":"تَخَلَّفَ تفعل سے ماضی واحد مذکر غائب، پیچھے رہ گئے۔ سَفْرَةٍ ایک سفر میں۔ سَافَرْنَاهَا مفاعلہ سے ماضی جمع متکلم ضمیر سفرۃ کی جانب لوٹتی ہے، ہم نے سفر کیا۔ فَأَدْرَكَنَا افعال سے ماضی واحد مذکر غائب ضمیر جمع متکلم، ہم نے پالیا۔ أَرْهَقَتْنَا افعال سے واحد مؤنث غائب ضمیر متکلم مفعول بہ ہے، ڈھانپ لیا یعنی نماز کا وقت تھا جس سے ہم نے جلدی کی۔ فَنَادَى مفاعلہ سے ماضی واحد مذکر غائب پکارا۔ آپ صلی اللہ علیہ وسلم نے وَيْلٌ یہ تہدید ہے، ہلاکت ہے۔"}],[555,"اور ابوداؤد و نسائی میں اس حدیث کے آخر میں ہے: ’’اچھی طرح وضو کرو‘‘","",{"k":"نسائی (111)۔ صحیح، البانی: 108۔ بخاری (163)۔ مسلم (241)۔ ابوداؤد (97)۔ ابن ماجہ (451)۔ احمد (7063)۔ دارمی (706)۔","m":"تَلُوحُ، نَصَر سے مضارع معلوم واحد مؤنث غائب، خشک ہونے کی وجہ سے چمک رہی ہیں۔ أَسْبِغُوا افعال سے امر جمع حاضر، پورا کرو۔"}],[556,"سیدنا ابو ہریرہ رضی اللہ عنہ سے اس کی مثل ہے اور امام ترمذی رحمہ اللہ کہتے ہیں نبی صلی اللہ علیہ وسلم سے مروی ہے کہ ایڑیوں اور پاؤں کے تلوؤں کے لیے آگ کا عذاب ہو گا۔","",{"k":"ترمذی (41)۔ اس کے متعلق البانی خاموش رہے ہیں، مگر صحیح الترغیب والترهیب: 216 میں اسے صحیح قرار دیا ہے۔ بخاری (165)۔ مسلم (242)۔ نسائی (110)۔ ابن ماجہ (7453)۔ احمد (10081)۔ دارمی (707)۔","m":"رُوِيَ، ضَرَب سے ماضی مجہول واحد مذکر غائب، مروی ہے۔ وَبُطُونِ اس کا واحد بَطْنٌ ہے، قدموں کے اندر کے حصے۔","e":"ان احادیث کے مجموعہ سے درج ذیل باتوں کا پتہ چلتا ہے۔ ۱۔ بلا وجہ چیخنے چلانے کی ضرورت نہیں نہ ہی یہ عمل بہتر ہے، بلکہ فضول ہے البتہ بوقت ضرورت علم کی بات بتاتے ہوئے، یا جمعہ پڑھاتے اور مجمع زیادہ ہو اور وعظ و نصیحت کرتے ہوئے بلند آواز سے پکارنا جائز ہے۔ ۲۔ ان احادیث میں ان لوگوں کی تردید ہے جو قرآن پاک کی آیت سے جر (زیر) والی قراءت وَأَرْجُلَكُمْ کہ اپنے پاؤں پر مسح کرو، سے استدلال کرتے ہیں، اور کہتے ہیں کہ پاؤں پر مسح کیا جائے دھویا نہ جائے۔ یہ دلیل پکڑنا غلط ہے کیونکہ یہ حدیث اور تواتر کی حد تک پہنچنے والی دیگر احادیث جو اللہ تعالیٰ کے اس فرمان کی تفسیر ہیں، ان سے ثابت ہوتا ہے پاؤں دھونے فرض ہیں، کیونکہ پاؤں کی معمولی جگہ خشک رہ جائے تو اسے آگ کی ڈانٹ دی گئی ہے، اس سے اس کی سنگینی کا علم ہوتا ہے۔ (تحفۃ الاحوذی: ۱/ ۵۰)"}],[557,"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے جنابت سے غسل کیا پھر آپ صلی اللہ علیہ وسلم نے خشک جگہ چمکتی دیکھی جس کو پانی نہیں پہنچا تھا پس آپ صلی اللہ علیہ وسلم نے اپنی زلف مبارک کے بال نچوڑ کر اس جگہ کو تر کر دیا۔","",{"k":"ابن ماجہ (663)۔ احمد (2181)۔ ضعیف، البانی: 144۔","e":"انتباہ: صحیح حدیث میں وضاحت اوپر گزر چکی ہے کہ پاؤں خشک رہ جائیں تو وضو دوبارہ کیا جائے وہی پانی مل دینا کافی نہیں۔"}],[558,"سیدنا جابر رضی اللہ عنہ سے عمامہ پر مسح کرنے کا پوچھا گیا تو انہوں نے کہا جائز نہیں جب تک بالوں پر پانی سے مسح نہ کیا جائے۔ (موطا)","",{"k":"موطا (67)۔ مع شرح زرقانی ماجاء فی المسح با الراس والاذنین۔"}],[559,"سیدنا ثوبان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک لشکر بھیجا، ان کو سردی لگی تو رسول اللہ صلی اللہ علیہ وسلم نے ان کو حکم دیا کہ وہ پٹیوں اور موزوں پر مسح کریں۔","",{"k":"ابوداؤد (146)۔ احمد (21878)۔ صحیح، البانی: 123۔","m":"سَرِيَّةٌ اس کی جمع سرایا ہے، لشکر کے ایک حصہ کو کہتے ہیں جو پانچ افراد سے لے کر چار سو افراد پر مشتمل ہوتا ہے۔ الْبَرْدُ دال پر جزم ہے، ٹھنڈک پہنچی۔ الْعَصَائِبِ ہر وہ چیز جو بل دے کر سر پر باندھی ہو، مراد یہاں پگڑیاں ہیں۔ اَلتَّسَاخِينِ ہر وہ چیز جو پاؤں پر لپیٹی ہو۔ موزے یا جرابیں، یہاں موزے مراد ہیں۔"}],[560,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو وضو کرتے وقت دیکھا آپ صلی اللہ علیہ وسلم پر خوشبو لگائی پگڑی تھی آپ صلی اللہ علیہ وسلم نے پگڑی کے نیچے ہاتھ داخل کر کے سر کے اگلے حصے پر مسح کیا اور پگڑی کو نہیں کھولا۔","",{"k":"ابوداؤد (147)۔ ابن ماجہ (564)۔ ضعیف، البانی: 25۔","e":"سیدنا جابر رضی اللہ عنہ کے فعل سے یہی واضح ہو رہا ہے کہ بالوں پر پہلے ضرور ہاتھ پھیرا جائے، پھر پگڑی پر مسح کیا جائے۔ مگر یہ ان کا اپنا فعل ہے، اصل بات یہ ہے کہ نبی اکرم صلی اللہ علیہ وسلم سے تین طرح پر سر کا مسح ثابت ہے (۱) صرف سر پر (۲) صرف پگڑی پر۔ (۳) کچھ سر کے اگلے حصہ پر اور دوسرا پگڑی پر۔ سیدنا جابر رضی اللہ عنہ نے ان میں سے ایک ہی طریقہ اختیار کر لیا ہے، مگر اتباع کے لائق پیغمبر صلی اللہ علیہ وسلم کا ہی طرز عمل ہے۔\nعلامہ عبداللہ رحمانی رحمہ اللہ پگڑی پر مسح نہ کرنے کے قائلین کے تمام اعتراضات کا رد بیان کرنے کے بعد فرماتے ہیں: فَقَدْ ثَبَتَ الْمَسْحُ عَلَى الرَّأْسِ فَقَط وَعَلَى الْعِمَامَةِ فَقَط وَعَلَى الرَّأْسِ وَالْعِمَامَةِ وَالْكُلُّ صَحِيحٌ ثَابِتٌ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَوْجُودٌ فِي كُتُبِ الْأَئِمَّةِ الصِّحَاحِ وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُبَيِّنٌ لِأَمْرِ اللَّهِ فَقَصْرُ الْإِجْزَاءِ عَلَى بَعْضِ مَا وَرَدَ لِغَيْرِ مُوجَبٍ لَيْسَ مِنْ دَأْبِ الْمُنْصِفِينَ. (مرعاۃ: ۱/ ۴۶۷) ’’صرف سر پر، صرف پگڑی پر اور کچھ سر کے اگلے حصہ اور دوسرا پگڑی پر تینوں طرح سر کا مسح کرنا صحیح اور رسول اکرم صلی اللہ علیہ وسلم سے ثابت ہے، صحیح کتابوں کے مؤلف بھی انہیں اپنی کتابوں میں لائے ہیں اور نبی اکرم صلی اللہ علیہ وسلم، اللہ تعالیٰ کے حکم کے لیے مفسرین کر آئے ہیں بغیر کسی وجہ سے ایک حصہ آپ کے فرمان پر ہی اکتفا کرنا کسی منصف مزاج کے لائق نہیں کہ ایک طریق پر مسح کرتا رہے بلکہ تینوں طرح مسح کرے یہی سنت طریقہ ہے۔‘‘"}],[561,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے وضو دو بار کیا۔","",{"k":"ترمذی (43)۔ ابوداؤد (136)۔ حسن، صحیح البانی: 40۔"}],[562,"ترمذی رحمہ اللہ نے جابر سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے ایک ایک بار، دو دو بار اور تین تین بار وضو کیا۔","",{"k":"ترمذی (43)۔ اس میں مرہ مرہ کا اضافہ بخاری (157) میں ہے۔"}],[563,"سیدنا عبد اللہ بن زید رضی اللہ عنہ سے روایت کی ہے آپ صلی اللہ علیہ وسلم نے دو دو بار وضو کیا۔","",{"k":"بخاری (158)۔ احمد (16017)۔ دارمی (694)۔ اس میں نور علی نور کے الفاظ بھی ہیں مگر یہ بخاری اور نسائی میں الفاظ نہیں ہیں۔"}],[564,"سیدنا عثمان رضی اللہ عنہ سے روایت ہے کہ آپ صلی اللہ علیہ وسلم نے تین تین بار وضو کیا اور فرمایا: ’’یہ میرا وضو ہے اور میرے سے پہلے کے تمام انبیاء کا وضو ہے اور ابراہیم علیہ السلام کا وضو ہے۔‘‘","",{"k":"رزین۔"}],[565,"نمران بن جاریہ اپنے باپ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سر کے مسح کے لیے نیا پانی کرو۔‘‘ (الکبیر)","",{"k":"طبرانی کبیر وفیہ دھثم بن قران ابن حبان نے اسے ثقات میں شمار کیا ہے، اور محدثین کی جماعت نے اسے ضعیف قرار دیا ہے۔","e":"انتباہ: پہلے اس مسئلہ کی وضاحت ہو چکی ہے کہ اعضائے وضو دو دو تین تین یا ایک ایک مرتبہ دھونا ہر طرح ثابت ہے۔"}],[566,"عباد بن تمیم اپنے باپ سے روایت بیان کرتے ہیں، انہوں نے کہا میں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم نے وضو کیا اور پانی ڈال کر پاؤں پر ہاتھ پھیرا۔ (الاوسط)","",{"k":"طبرانی اوسط رجالہ الرجال الصحیح طبرانی کا شیخ ثقہ نہیں۔"}],[567,"عبد اللہ بن بدر رضی اللہ عنہ نے کہا: قرآن نازل ہوا مسح کرنے کے ساتھ اور رسول اللہ صلی اللہ علیہ وسلم نے ہمیں دھونے کا حکم دیا تو ہم نے دھویا۔ (الکبیر بسند ضعیف)","",{"k":"طبرانی کبیر عبداللہ بن بدر تابعی ہیں، اس میں محمد بن جابر ضعیف ہے۔"}],[568,"سیدنا ابن مسعود رضی اللہ عنہ نے کہا: اللہ کا فرمان: ’’اور پاؤں کو ٹخنوں تک۔‘‘ یہ پاؤں دھونے کی طرف لوٹ آیا ہے۔ (الکبیر)","",{"k":"طبرانی کبیر، 9210۔ اور قتادہ نے ابن مسعود سے روایت نہیں سنی۔ ہیثمی: 1194۔"}],[569,"ابوایوب رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میری امت میں سے وضو کرتے اور کھانا کھاتے وقت خلال کرنے والے بہت اچھے ہیں۔‘‘","",{"k":"احمد (23016)۔ طبرانی کبیر وفی اسنادہ واصل بن السائب یہ ضعیف ہے یہ الفاظ احمد کے ہیں، واخرجہ ابن ماجہ 433۔"}],[570,"سیدنا ایوب رضی اللہ عنہ سے روایت ہے کہ لوگوں نے عرض کی: یا رسول اللہ! خلال کیا ہے؟ فرمایا وضو میں خلال کرنا تو منہ میں اور ناک میں پانی ڈالنا اور کھانے کا خلال کھانا کھانے کے بعد ہے۔ فرشتوں پر اس سے زیادہ سخت اذیت کوئی نہیں ہے کہ وہ اپنے متعلقہ ساتھی کے دانتوں میں نماز پڑھتے وقت کھانے کے ریزے دیکھیں۔","",{"k":"طبرانی کبیر: 4061۔ احمد، وفی اسنادہما واصل الرقاشی وهو ضعیف، ہیثمی: 1199۔"}],[571,"سیدنا ابو درداء رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے وضو کیا اور داڑھی کا خلال کیا وضو کے بقیہ پانی سے اور سر کا مسح کیا بازؤں کے بقیہ پانی سے۔‘‘ (الکبیر بسند ضعیف)","",{"k":"طبرانی کبیر اس میں تمام بن نجیح ہے، یحیی بن معین نے صرف اسے ثقہ کہا ہے۔ بخاری اور ایک جماعت نے اسے ضعیف قرار دیا ہے۔ ہیثمی: 1205۔"}],[572,"سیدنا عثمان رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم داڑھی کا خلال کیا کرتے تھے۔ (ترمذی)","",{"k":"ترمذی (31)۔ ابن ماجہ (430)۔ صحیح، البانی: 28۔","m":"يُخَلِّلُ تفعیل سے مضارع معلوم واحد مذکر غائب، انگلیاں داڑھی کے درمیان پھیرنا۔ لِحْيَتِهِ داڑھی، اس کی جمع لحی ہے۔"}],[573,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم جب وضو کرتے تو ہتھیلی میں پانی لے کر ٹھوڑی کے نیچے داخل کر کے داڑھی کا خلال کرتے اور فرماتے تھے: ’’میرے رب تعالیٰ نے اسی طرح کرنے کا حکم دیا ہے۔‘‘","",{"k":"ابوداؤد (145)۔ ابن ماجہ (431)۔ صحیح، البانی: 132۔","m":"حَنَكِهِ اس کی جمع أَحْنَاک ہے، ٹھوڑی کے نیچے والا حصہ۔"}],[574,"سیدنا ابو وائل رضی اللہ عنہ سے بھی اس کی مثل منقول ہے اور اس میں یہ بھی ہے کہ داڑھی کا خلال منہ دھونے کے وقت میں کیا ہے اور کانوں کے اندرونی حصے کا، گردن کا اور داڑھی کے اندر کا مسح کیا سر کے باقی پانی سے۔ دونوں بازو کو کہنیوں سے اوپر تک دھویا، پاؤں کی انگلیوں کا خلال کیا اور ٹخنوں سے اوپر پنڈلی تک بڑھایا، پھر دائیں ہاتھ میں پانی لیا اور اپنے سر پر رکھ دیا یہاں تک کہ پانی سر کے اطراف سے گرنے لگا اور فرمایا: ’’مکمل وضو یہ ہے۔‘‘","",{"k":"بزار: 268۔ طبرانی کبیر وفیہ سعید بن عبدالجبار، قال النسائی لیس بالقوی وذکرہ ابن حبان فی الثقات وفی سند البزار والطبرانی محمد بن حجر وہو ضعیف۔"}],[575,"سیدنا واثلہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو پانی کے ساتھ اپنی انگلیوں میں خلال نہیں کرے گا تو اللہ تعالیٰ آگ سے قیامت کے دن خلال کر دے گا۔‘‘","",{"k":"طبرانی کبیر: 3400۔ اس میں علاء ہیں کثیر لیثی ہو مجمع علی ضعیفہ۔"}],[576,"سیدنا ابن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’انگلیاں وضو کے وقت کھولی جائیں یا پھر آگ ان کو کھول دے گی۔‘‘ (الاوسط)","",{"k":"طبرانی اوسط: 9211۔ ووقفہ فی الکبیر علی ابن مسعود، واسنادہ حسن، ہیثمی: 1210۔","m":"لَتَنْتَهِكُنَّ لام تاکید ہے، نون ثقیلہ افتعال سے مضارع معلوم واحد مؤنث غائب، یعنی حلال کرو۔"}],[577,"سیدنا ابن عباس رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تو وضو کرے تو اپنے ہاتھوں اور پاؤں کی انگلیوں کا خلال کیا کر۔‘‘ (ترمذی)","",{"k":"ترمذی (39)۔ ابن ماجہ (447)۔ حسن صحیح، البانی: 36۔","m":"فَخَلِّلْ تفعل سے امر حاضر ہے، خلال کر۔","e":"ان تمام احادیث سے یہ ثابت ہوتا ہے کہ داڑھی اور پاؤں کا خلال ضروری ہے۔ وہ اس طرح کہ داڑھی کے بالوں کے درمیان انگلیاں پھیری جائیں اور ٹھوڑی کے نیچے پانی ڈالا جائے اور خلال کیا جائے اور پاؤں کی انگلیوں کا خلال یہ ہے کہ سب سے چھوٹی انگلی پاؤں کی انگلیوں کے درمیان پھیری جائے۔ (ترمذی) بعض احادیث میں امر کا صیغہ آیا ہے، جو خلال کے واجب ہونے پر دلالت کرتا ہے، بعض حضرات نے اس خلال کو غیر مشروع قرار دیا ہے یہ احادیث ان کے نظریہ کی تردید کے لیے کافی ہیں۔ باقاعدہ پاؤں اور ہاتھوں کی انگلیاں داڑھی کا خلال کرنا مسنون ومشروع ہے۔ (مرعاۃ: ۱/۴۷۳)"}],[578,"لقیط بن صبرہ رضی اللہ عنہ سے مروی ہے کہ میں نے عرض کی یا رسول اللہ! مجھے وضو کا طریقہ سکھا دیجیے۔ فرمایا مکمل وضو کر انگلیوں کے درمیان خلال کر اور ناک میں پانی ڈالنے میں خوب مبالغہ کر مگر جب تو روزے سے ہو تو احتیاط کرنا۔","",{"k":"نسائی (87)۔ ترمذی (788)۔ ابوداؤد (2366)۔ ابن ماجہ (448)۔ احمد (17390)۔ دارمی (705)۔ صحیح، البانی: 85۔","m":"وَبَالِغْ مفاعلہ سے امر حاضر ہے واحد مذکر، مبالغہ کر یعنی اچھی طرح پانی پہنچاؤ۔","e":"اس میں وضو کے مقامات میں خوب دھونے کا حکم ہے اور وضو کا ہر عضو دھوتے ہوئے حق ادا کر دو، اچھی طرح انہیں ملو۔\n۲۔ اس میں دلیل ہے کہ ناک میں پانی داخل کرنا اور کلی کرنا واجب ہے۔ ناک میں پانی خوب گہرائی سے داخل کیا جائے مگر روزے کی حالت میں اتنا مبالغہ نہ کیا جائے کہ پانی حلق میں اتر جائے۔ ۳۔ سائل نے وضو کے متعلق پوچھا تھا، مگر نبی اکرم صلی اللہ علیہ وسلم نے یہ دو باتیں ہی جواب میں بتائی ہیں، وجہ یہ ہے کہ دیگر اعضائے وضو کا سائل کو علم تھا۔ اس لیے نبی اکرم صلی اللہ علیہ وسلم نے اسی پر اکتفا کیا۔ (مرعاۃ: ۱/۴۷۲)"}],[579,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر میری امت کے لیے مشکل نہ ہوتا تو میں ان کو مسواک کا حکم دیتا۔‘‘","",{"k":"بخاری (7240)۔ مسلم (252)۔ ترمذی (22)۔ نسائی (7)۔ ابوداؤد (46)۔ ابن ماجہ (287)۔ احمد (10487)۔ مالك: 148۔ دارمی (683)۔","m":"أَشُقَّ، نَصَر سے مضارع معلوم واحد متکلم میں مشقت نہ سمجھتا با السِّوَاكِ یہ مسواک کرنے کے عمل پر بھی بولا جاتا ہے اور اس لکڑی کو بھی کہتے ہیں جس کے ساتھ مسواک کی جائے۔"}],[580,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر میری امت کے لیے مشکل نہ ہوتا تو میں ان کو ہر نماز کے ساتھ مسواک کرنے کا حکم دیتا۔‘‘","",{"k":"بخاری (887)۔ بقیہ 579 والی تخریج ہے۔"}],[581,"احمد کی روایت میں ہے کہ وضو کا اور ہر وضو کے ساتھ مسواک کرنے کا حکم دیتا۔","",{"k":"احمد (7461)۔ طبرانی کبیر اس میں محمد بن عمرو بن علقمہ یہ ثقہ اور حسن الحدیث ہے، بخاری (7494)۔ مسلم (758)۔ ترمذی (22)۔ نسائی (534)۔ ابوداؤد (4733)۔ ابن ماجہ (1761)۔ مالك: 496۔ دارمی (1720)۔"}],[582,"زید بن خالد رضی اللہ عنہ نمازوں کے لیے مسجد میں حاضر ہوتے اور ان کا مسواک ان کے کان پر رکھا ہوتا تھا جہاں کاتب اپنا قلم رکھتا ہے وہ جب بھی نماز کے لیے اٹھتے تو مسواک کرتے اور پھر مسواک اس کی جگہ پر رکھ دیتے تھے۔","",{"k":"ترمذی (23)۔ ابوداؤد (47)۔ صحیح، البانی: 22۔","m":"اسْتَنَّ افتعال ماضی واحد مذکر غائب، مسواک کرتے۔ رَدَّهُ، نَصَر سے ماضی واحد مذکر غائب ضمیر مسواک کی طرف لوٹتی ہے، اس مسواک کو کان کی اسی جگہ پر لوٹا دیتے۔"}],[583,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم رات یا دن جس وقت بھی سوتے تھے تو بیدار ہو کر وضو سے پہلے مسواک کرتے تھے۔","",{"k":"ابوداؤد (57)۔ اس میں ولا نہار کے الفاظ کے علاوہ یہ حسن ہے۔ البانی: 51۔ مسلم (253)۔","m":"لَا يَرْقُدُ مضارع منفی واحد مذکر غائب، سوتے نہ تھے۔ فَيَسْتَيْقِظُ استفعال سے مضارع معلوم واحد مذکر غائب بیدار ہوتے۔ تَسَوَّكَ تفعل سے ماضی واحد مذکر غائب، مسواک کرتے۔"}],[584,"شریح بن ہانی رضی اللہ عنہ سے مروی ہے کہ میں نے عائشہ رضی اللہ عنہا سے سوال کیا کہ نبی کریم صلی اللہ علیہ وسلم جب اپنے گھر میں داخل ہوتے تو سب سے پہلے کیا کام کرتے تھے؟ انہوں نے جواب دیا کہ مسواک کرتے تھے۔","",{"k":"مسلم (253)۔ کتاب الطہارۃ، نسائی (8)۔ ابوداؤد (51)۔ ابن ماجہ (290)۔ احمد (25466)۔","m":"بِأَيِّ شَيْءٍ کونسی چیز ہے؟ يَبْدَأُ مضارع معلوم واحد مذکر غائب مہموز اللام، آغاز کرتے۔"}],[585,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسواک منہ کے لیے طہارت اور رب کریم کی رضا کا ذریعہ ہے۔‘‘","",{"k":"نسائی (5)۔ احمد (25483)۔ دارمی (684)۔ صحیح، البانی: 5۔","m":"مَطْهَرَةٌ یہ مصدر میمی ہے، پاکیزگی۔ مَرْضَاةٌ یہ عَلِمَ سے مصدر میمی ہے۔ رضا مندی۔"}],[586,"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسواک منہ کی طہارت اور رب کی رضا کا ذریعہ ہے اور آنکھوں کو روشن کرتا ہے۔‘‘","",{"k":"طبرانی کبیر، اس میں بحر بن کنیز سقاء ہے اس کے ضعف پر اجماع ہے۔ ہیثمی: 1115۔"}],[587,"سیدنا ابو موسیٰ رضی اللہ عنہ سے منقول ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا تو آپ صلی اللہ علیہ وسلم مسواک کرتے اور اع اع کہہ رہے تھے اور مسواک آپ کے منہ میں تھا۔ لگتا تھا آپ صلی اللہ علیہ وسلم قے کر رہے ہیں۔","",{"k":"بخاری (244)۔ مسلم (254)۔ نسائی (3)۔ ابوداود (49)۔","m":"أَعْ أَعْ جو گلے سے آواز نکلتی ہے۔ فِي فِيهِ جری حالت ہے، آپ صلی اللہ علیہ وسلم کے منہ میں تھی۔ يَتَهَوَّعُ تفعل سے مضارع معلوم واحد مذکر غائب ہے، قے آنے کی مانند آواز نکالتے تھے۔"}],[588,"ابوداؤد کی روایت میں ہے: جب میں آپ صلی اللہ علیہ وسلم کے پاس گیا تو آپ صلی اللہ علیہ وسلم مسواک کر رہے تھے۔ مسواک کو زبان کے کنارے پر رکھا تھا۔","",{"k":"صحیح، البانی: 39۔ بخاری (244)۔ مسلم (254)۔ نسائی (3)۔ احمد (19228)۔","m":"يَسْتَاكُ افتعال سے مضارع معلوم واحد مذکر غائب، مسواک کر رہے تھے۔ طَرَفِ کنارہ۔"}],[589,"نسائی کی روایت ہے کہ آپ صلی اللہ علیہ وسلم عاعا کر رہے تھے۔","",{"k":"نسائی (3)۔ صحیح، البانی: 3۔ بقیہ تخریج نمبر 588 والی ہے۔","m":"عَأْعَا مسواک زبان پر رکھیں اور اسے استعمال کرنے سے پیدا ہونے والی آواز۔"}],[590,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں نے مسواک کی تمہیں بکثرت تاکید کی ہے۔‘‘ (بخاری و نسائی)","",{"k":"بخاری (888)۔ نسائی (6)۔ احمد (13186)۔ دارمی (681)۔","m":"أَكْثَرْتُ افعال سے ماضی واحد متکلم، میں نے بہت زیادہ مبالغہ سے مسواک کرنے کا کہا ہے۔"}],[591,"نسائی کی دوسری روایت ہے: ’’تم نے مسواک کے متعلق مجھ سے بکثرت سوال کیا ہے۔‘‘","",{"k":"نسائی (6)۔ صحیح، البانی۔ بخاری (888)۔ احمد (12050)۔ دارمی (681)۔"}],[592,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم مسواک کر رہے تھے اور آپ صلی اللہ علیہ وسلم کے پاس دو مرد موجود تھے۔ ایک عمر میں دوسرے سے بڑا تھا پس آپ صلی اللہ علیہ وسلم پر مسواک کی فضیلت کی وحی نازل ہوئی کہ مسواک بڑے کو دو۔ وہ کہتی ہیں: آپ صلی اللہ علیہ وسلم مسواک کرتے اور دھونے کے لیے مجھے دیتے تو میں پہلے خود مسواک کرتی اور پھر دھوتی اور پھر اٹھا کر آپ صلی اللہ علیہ وسلم کو دیدیتی تھی۔‘‘ (ابوداؤد)","",{"k":"ابوداود (50)۔ صحیح البانی، 40۔","m":"فَأَوْحَى افعال سے ماضی مجہول، وحی کی گئی۔ إِلَيْهِ آپ صلی اللہ علیہ وسلم کی طرف۔ كَبِّرْ تفعیل سے امر حاضر واحد مذکر، یعنی مسواک دینے میں بڑے کو مقدم رکھو۔ یہ اوحی کا نائب فاعل ہے۔ أَعْطِ افعال سے امر واحد مذکر حاضر، دو۔ یہ پہلے جملہ کی تفسیر ہے، یہ بھی نبی صلی اللہ علیہ وسلم کا قول ہے۔ (عون المعبود: ۱/ ۱۹)"}],[593,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: مسواک کے ساتھ ایک نماز پڑھنا بغیر مسواک کے ستر نمازوں کے برابر ہے۔‘‘ (احمد، موصلی، براز)","",{"k":"احمد (25808)۔ ابو یعلی، بزار، وقد صححه الحاكم، هيثمي: 2554۔","m":"ضِعْفًا ستر گنا۔"}],[594,"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جب بندہ مسواک کرتا ہے اور پھر نماز کے لیے کھڑا ہوتا ہے تو فرشتہ اس کے پیچھے کھڑا ہو کر قریب سے اس کی نماز کی قراءت سنتا ہے (یا اس کی مثل کلمہ ارشاد فرمایا) اور قریب آ کر اس کے منہ کے اوپر فرشتہ اپنا منہ رکھ دیتا ہے تو جو کلمات قرآن مجید کے اس کے منہ سے خارج ہوتے ہیں وہ فرشتے کے منہ میں داخل ہو جاتے ہیں۔ پس تم اپنے منہ قرآن کے لیے پاک رکھو۔‘‘ (بزار)","",{"k":"بزار، ورجاله ثقات البزار، هيثمي: 2564۔","m":"فَيَسْتَمِعُ افتعال سے مضارع معلوم واحد مذکر غائب غور سے سنتا ہے۔ فَيَدْنُو، نَصر سے مضارع معلوم واحد مذکر غائب، وہ قریب ہوتا ہے۔ مِنْهُ اس بندے کے۔ فَاهُ یہی حالت ہے، اپنا منہ۔ عَلَى فِيهِ یہ جر کی حالت ہے، اس بندے کے منہ پر۔ فَمَا نہیں۔ فَطَهِّرُوا تفعیل سے امر حاضر ہے، جمع مذکر، پاک کرو۔ أَفْوَاهَكُمْ، فَم کی جمع ہے، اپنے مونہوں کو۔"}],[595,"سیدہ عائشہ رضی اللہ عنہا کہتی ہیں: میں نے عرض کی یا رسول اللہ! اگر کسی انسان کے منہ میں دانت ہی نہ ہوں تو مسواک کیسے کرے؟ فرمایا: ’’منہ میں انگلی ڈال کر اس کو رگڑ دے۔‘‘ (الاوسط بسند ضعیف)","",{"k":"طبرانی اوسط اس میں عیسی بن عبداللہ انصاری ضعیف ہے۔ هیثمی: 2574۔"}],[596,"سیدنا معاذ رضی اللہ عنہ روایت کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا کہ آپ نے فرمایا: ’’عمدہ مسواک زیتون کے بابرکت درخت کا ہے۔ وہ منہ کو پاک کرتا ہے اور دانتوں کی زردی کو دور کرتا ہے میرا یہی مسواک ہے اور یہ مجھ سے پہلے کے انبیاء کا مسواک ہے۔‘‘ (الاوسط، اور اس میں معلل بن محمد راوی ہے)","",{"k":"طبرانی اوسط، اس میں معلل بن محمد ہے، اس کا کسی نے تذکرہ نہیں کیا یہ کون ہے؟ هیثمی: 2576۔"}],[597,"ابو خیرہ الصباحی رضی اللہ عنہ نے کہا: میں اس وفد میں شامل تھا جو نبی صلی اللہ علیہ وسلم کے پاس آیا تھا پس آپ صلی اللہ علیہ وسلم نے ہمیں پیلو کے درخت کے مسواک دیئے تا کہ ہم مسواک کریں۔ ہم نے عرض کی: یا رسول اللہ! ہمارے پاس کھجور کی ٹہنی موجود ہے مگر آپ صلی اللہ علیہ وسلم کا اکرام اور عطیہ برکت کے لیے قبول کرتے ہیں تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’یا اللہ! عبدالقیس خاندان کی مغفرت کر دے۔‘‘ (یہ الکبیر کی طویل روایت سے ہے)","",{"k":"طبرانی کبیر، واسناد حسن: 2575۔","m":"الْوَفْدُ خاص لوگ جو دوسری جگہ نمائندہ بن کر گئے ہوں۔ أَتَوْا ماضی جمع مذکر غائب، وہ آئے۔ فَزَوَّدَنَا تفعیل سے ماضی واحد مذکر غائب ضمیر مفعول بہ ہے، ہمیں تحفہ دیا۔ الْأَرَاكُ جھاؤ کا درخت ہے۔ بِهِ اس لکڑی کے ساتھ۔ الْجَرِيدُ کھجور کی شاخ۔ كَرَامَتَكَ جو عزت و کرامت دی۔"}],[598,"سیدنا ابو امامہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسواک کیا کرو وہ منہ کو پاک کرنے والا اور رب تعالیٰ کی رضا کا باعث ہے اور میرے پاس جب بھی جبریل علیہ السلام تشریف لائے مجھے مسواک کی تلقین کرتے رہے۔ مجھے خوف پیدا ہونے لگا کہ میرے اوپر اور میری امت پر فرض ہی کر دیا جائے گا اور اگر مجھے یہ خوف نہ ہو کہ میں اپنی امت پر زیادہ مشقت ڈال دوں گا تو میں ان پر مسواک فرض ہی کر دیتا اور میں اس قدر مسواک کرتا ہوں کہ مجھے خوف پیدا ہوتا ہے کہ میں اپنے منہ کا اگلا حصہ کھود ڈالوں گا۔‘‘ (قزوینی بسند ضعیف)","",{"k":"ابن ماجه (289)۔ احمد (21766)۔ ضعیف، البانی: 58۔","e":"ان تمام احادیث سے مسواک کے فضائل اور مسواک کرنے کا طریقہ اور طہارت و پاکیزگی میں اس کی اہمیت واضح ہوتی ہے اور اس کی عظمت کے لیے یہی کافی ہے کہ آپ صلی اللہ علیہ وسلم مسواک بطور تحفہ وفد کو دے رہے ہیں۔ اور صحابی رضی اللہ عنہ یاد دہانی کے لیے اپنے کان پر رکھتے ہیں، مسواک کرنے کی مزید تفصیل ملاحظہ فرمائیں ۱۔ ویسے تو کسی بھی درخت سے مسواک کرنا جائز ہے اور احادیث میں مذکور ثواب حاصل ہوتا ہے۔ مگر نبی صلی اللہ علیہ وسلم سے جھاؤ کے درخت کی مسواک کرنا پسندیدہ طور پر ثابت ہے جیسا کہ اوپر حدیث میں آیا ہے کہ آپ نے وفد کو اسی درخت کی مسواک کا تحفہ دیا تھا۔ ۲۔ مسواک کرنے کا طریقہ جو صحیح ترین احادیث سے ثابت ہوا ہے وہ یہ ہے کہ دانتوں کی نچلی طرف سے اوپر کی جانب کی جائے یا دانتوں پر لمبائی کے طور پر مسواک پھیری جائے۔ ۳۔ آج کل جو برش وغیرہ ہیں، ان میں احتیاط یہ مدنظر رکھیں کہ اگر بالوں والے ہوں تو کسی حرام جانور کے نہ ہوں۔ اگر حلال جانور کے ہوں یا پلاسٹک وغیرہ حلال چیز سے ہوں تو ان کو دانتوں پر پھیریں یا پیسٹ لگائیں تو ثواب مسواک والا ہی ہوگا۔ مگر تجربہ سے ثابت ہے اصل صفائی مسواک ہی سے حاصل ہوتی ہے۔ ۴۔ مسواک وضو کے وقت علیحدہ اور نماز سے پہلے علیحدہ کرنا ان احادیث سے ثابت ہے اور ذکر الہی اور تلاوت قرآن کے وقت مسواک کی خصوصی تلقین ہوئی ہے کیونکہ ان اوقات میں فرشتوں کا قرب ہوتا ہے اور قرب الہی ہوتا ہے۔ بندے کو درس دیا گیا ہے کہ وہ کامل نظافت اور طہارت سے یہ قرب حاصل کرے اور یہ مسواک بلغم وغیرہ ختم کرتی ہے، تلاوت میں مزید فصاحت پیدا کرنے کے لیے اس وقت مسواک کی ترغیب ہے اور فرشتے بالکل قریب آنے میں دقت محسوس نہیں کرتے۔ اور یہی صفائی ہے جو مسواک کی وجہ سے حاصل ہوتی ہے کہ مسواک والی نماز دوسری سے ستر گناہ ثواب میں بڑھ جاتی ہے۔ ۵۔ یہ بھی ثابت ہوتا ہے کہ مسواک کا اہتمام ہمہ وقت کیا جائے نماز یا غیر نماز وضو یا وضو کے علاوہ بھی اور چلتے پھرتے اور بیٹھے ہر وقت کی جاسکتی ہے اور یہ ایک فطرتی عمل ہے انبیائے کرام علیہم السلام اور پیغمبر آخر الزماں صلی اللہ علیہ وسلم سب مسواک کرتے رہے ہیں۔ ۶۔ دوسرے کی استعمال شدہ مسواک بھی کی جاسکتی ہے۔ (ابوداؤد، وسکت عنه المنذری، مرعاۃ: ۱/ ۴۴۷) ۷۔ روزے کی حالت میں بھی مسواک کی جاسکتی ہے۔ جیسا کہ امام نسائی رحمہ اللہ نے ایک حدیث سے استدلال کیا ہے۔ (۳/۱، کتاب الطہارۃ باب الرخصة في السواك بالعشى للصائم)"}],[599,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی آدمی اپنی نیند سے بیدار ہو تو وہ اپنا ہاتھ برتن میں نہ ڈالے یہاں تک کہ تین بار اس کو دھولے کیونکہ وہ نہیں جانتا کہ اس کا ہاتھ رات کہا رہا ہے۔‘‘ (صحاح ستہ)","",{"k":"مسلم (278)۔ كتاب الطهارة، بخارى (162)۔ ترمذی (24)۔ نسائی (441)۔ ابوداود (105)۔ ابن ماجه (393)۔ احمد (10211)۔ مالك: 40۔ دارمی (766)۔","m":"فَلَا يَغْمِسْ، ضَرَب سے، نہی واحد مذکر غائب، برتن میں ہاتھ نہ ڈال۔ فَإِنَّهُ یقیناً وہ آدمی۔ لَا يَدْرِى مضارع منفی واحد مذکر غائب، وہ نہیں جانتا۔ أَيْنَ کہاں۔ بَاتَتْ ماضی واحد مونث غائب، رات گزاری۔"}],[600,"ابوداؤد کی ایک روایت میں ہے: ’’وہ نہیں جانتا کہ وہ رات بھر کہاں رہا یا اس کا ہاتھ کہاں پھرتا رہا ہے۔‘‘","",{"k":"ابوداود (105)۔ صحیح، البانی: 96۔ بقیہ نمبر 599 والی تخریج ہے۔","m":"تَطُوفُ مضارع معلوم واحد مؤنث، گردش کرتا ہے۔","e":"اس حدیث سے یہ بھی ثابت ہوا کہ نجاست اور پلیدی کو تین بار دھویا جائے یہ حکم جس نجاست کے بارے وہم سا ہو اسے دھونے کا ہے، ظاہر ہے جو نجاست وجود رکھے اسے تو بالا ولی تین مرتبہ دھونا ہے۔\n۲۔ عبادات اور دیگر معاملات میں احتیاط سے کام لینا مستحب ہے۔ البتہ احتیاط سے کام لیتے ہوئے وسوسہ سے بھی بچنا چاہیے، زیادہ وہم کا شکار نہیں ہونا چاہیے۔ ۳۔ برتن میں بغیر دھونے کے ہاتھ نہ ڈالنے کا حکم اس کے لیے ہے جو رات سو کر اٹھتا ہے، دن والا اس کا پابند نہیں۔ رات سوتے وقت میل کچیل، یا کسی بھی گندی جگہ پر ہاتھ لگ سکتا ہے۔ اس لیے پہلے ہاتھوں کو باہر دھویا جائے پھر برتن میں ڈالا جائے تاکہ پانی گندہ ہونے سے محفوظ رہے۔ یاد رہے کہ یہ حکم احتیاط اور صفائی کے لیے ہے اگر کوئی بغیر دھوئے پانی کے برتن میں ہاتھ ڈال دیتا ہے، اس نے نبی اکرم صلی اللہ علیہ وسلم کے فرمان کی خلاف ورزی کی ہے۔ مگر پانی پلید نہ ہوگا۔"}],[601,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو وضو کرے تو ناک جھاڑے اور جو خوشبو لگائے تو طاق بار لگائے۔‘‘","",{"k":"بخاری (161)، مسلم (237)، نسائی (88)، ابوداود (35)، ابن ماجہ (409)، احمد (9653)، مالک: 33، دارمی (703)","m":"فَلْيَسْتَنْثِرْ استفعال سے امر غائب واحد مذکر، وضو کرنے والا جو پانی ناک میں جذب کرتا ہے، اسے باہر پھینکنے کے لیے جھاڑنا۔ اِسْتَجْمَرَ استفعال سے ماضی واحد مذکر غائب جو استنجاء کے لیے پتھر استعمال کرے۔ فَلْيُوتِرْ افعال سے امر غائب واحد مذکر اسے وتر کرے یعنی طاقت استعمال کرے۔"}],[602,"ہمام بن منبہ نے بیان کیا کہ یہ وہ روایت ہے کہ ابو ہریرہ رضی اللہ عنہ نے محمد رسول اللہ صلی اللہ علیہ وسلم سے بیان کیا اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی وضو کرے تو ناک کے ہر دو سوراخوں میں پانی پہنچائے پھر ناک جھاڑ دے۔‘‘","",{"k":"مسلم (237)، بخاری (162)، نسائی (88)، ابوداود (140)، ابن ماجہ (409)، احمد (10340)، مالک: 34، دارمی (703)","m":"فَلْيَسْتَنْشِقْ استفعال سے امر غائب واحد مذکر، ناک میں پانی جذب کرنا۔ بِمَنْخِرَيْهِ اس میں تثنیہ کا نون اضافت کی وجہ سے گرا ہے، ناک کے دونوں نتھنے۔"}],[603,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی آدمی اپنی نیند سے بیدار ہو تو وضو کرے اور ناک جھاڑے اس لیے کہ شیطان رات کو اس کی ناک پر رہتا ہے۔‘‘","",{"k":"نسائی (90)، صحیح، البانی: 88، بخاری (3295)، مسلم (238)، احمد (8408)","m":"خَيْشُومِهِ اس کی جمع خَيَاشِيمُ ہے، ناک کا بانسہ۔ يَبِيتُ، بَاتَ سے مضارع معلوم واحد مذکر غائب، رات گزارتا ہے۔"}],[604,"ابن عباس رضی اللہ عنہما مرفوع بیان کرتے ہیں: ’’مبالغہ کر کے دو یا تین بار ناک میں پانی ڈال کر جھاڑ دیا کرو۔‘‘ (ابوداؤد)","",{"k":"ابوداود (141)، ابن ماجہ (408)، صحیح البانی: 128","m":"بَالِغَتَيْنِ یہ اسم فاعل تثنیہ مؤنث ہے، یہ مَرَّتَيْنِ کی صفت ہے، یعنی دو مرتبہ پوری طرح جھاڑو۔","e":"۱۔ ان احادیث میں یہ بیان ہوا ہے کہ جب سو کر اٹھیں تو وضو سے پہلے تین مرتبہ ناک جھاڑا جائے یہ بہت ضروری ہے کیونکہ شیطان ناک کے بانسے میں رات گزارتا ہے، وہ کیسے گزارتا ہے اس پر ایمان لانا ہے اس کی کیفیت اللہ جانتا ہے۔ اس شیطان کے اثرات بددل تک جا سکتے ہیں کیونکہ بانسے سے دل میں اثر پہنچانے کے لیے سوراخ ہوتا ہے۔ اس لیے ناک جھاڑنے کی تاکید ہے کہ اس کے برے اثرات اور آلودگی سے دل محفوظ رہ جائے۔ ۲۔ استنجاء طاق کیا جائے جو کہ کم از کم تین پتھر ہیں۔ زیادہ بھی ہوں تو طاق رہیں، جفت نہ ہوں۔ ۳۔ ناک میں پانی ڈالیں تو اسے جھاڑیں وضو کرتے ہوئے اس کا خاص خیال رکھیں، البتہ روزہ ہو تو پھر پانی ناک میں مبالغہ سے داخل نہ کریں اس کے علاوہ مبالغہ سے پانی داخل کریں اور اسے خوب جھاڑیں۔ یہ اوپر وضاحت گزر چکی ہے کہ اعضائے وضو ایک ایک مرتبہ یا دو دو مرتبہ یا تین تین مرتبہ ہر طرح دھونا جائز ہے، اسی طرح ناک جھاڑنا بھی ہر طرح جائز ہے۔"}],[605,"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم سے سنا کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’میری امت قیامت کے دن سفید اعضاء والی کہلائے گی پس جو تم میں سے اپنے اعضاء کی سفیدی زیادہ کر سکے تو ضرور ایسا کرے۔‘‘ (بخاری و مسلم)","",{"k":"بخاری (136)، مسلم (246)، ابن ماجہ (4306)، احمد (10399)، مالک: 60","m":"أُمَّتِي میری امت، مراد امت کے مسلمان لوگ ہیں۔ يُدْعَوْنَ، نَصَرَ سے مضارع مجہول جمع مذکر غائب، پکارے جائیں گے۔ غُرًّا اس کا واحد أَغَرُّ ہے۔ یہ مفعول ہونے یا حال ہونے کی وجہ سے منصوب ہے، اصل میں یہ گھوڑے کی پیشانی میں جو سفیدی ہوتی ہے اسے کہتے ہیں۔ اس کا استعمال جمال اور خوبصورتی میں بھی ہوتا ہے۔ وہ نور جو روز قیامت آپ صلی اللہ علیہ وسلم کی امت کے لوگوں کی پیشانیوں میں نظر آئے گا یعنی جب انہیں پکارا جا رہا ہوگا تو ان کی حالت یہ ہوگی کہ چہرے پر نور نکل رہا ہوگا۔ مُحَجَّلِينَ یہ تفعیل سے اسم مفعول ہے، یہ بھی حال ہونے کی وجہ سے منصوب ہے، گھوڑے کے تین پاؤں سفید ہوں تو اسے کہتے ہیں۔ مراد وہی نور ہے۔ أَنْ يُطِيلَ افعال سے مضارع معلوم واحد مذکر غائب آن ناصبہ ہے، یہ کہ لمبا کرے۔"}],[606,"نعیم بن مجمر نے کہا کہ میں نے ابو ہریرہ رضی اللہ عنہ کو دیکھا جب وہ وضو کر رہے تھے، انہوں نے منہ دھویا اور پوری طرح پانی لگایا پھر دایاں ہاتھ دھویا یہاں تک کہ موٹے بازو کے نصف تک پانی پہنچا دیا پھر بایاں بازو دھویا تو پھر بھی موٹے بازو کے نصف تک پانی پہنچا دیا اور پھر بایاں پاؤں دھویا یہاں تک کہ پنڈلی تک پانی پہنچایا اور پھر بایاں پاؤں دھویا تو پنڈلی تک پانی لگایا۔ پھر انہوں نے کہا میں نے نبی کریم صلی اللہ علیہ وسلم کو اسی طرح وضو کرتے دیکھا ہے اور آپ صلی اللہ علیہ وسلم نے یہ فرمایا ہے کہ تم بروز قیامت سفید اعضاء والے ہو گے مکمل وضو کے سبب پس تم میں سے جس کو طاقت ہو اپنی سفیدی اور چمک زیادہ کرے۔‘‘","",{"k":"مسلم (246)، کتاب الطہارۃ، بخاری (136)، نسائی (150)، ابن ماجہ (4306)، احمد (10399)، دارمی (60)","m":"أَشْرَعَ افعال سے ماضی واحد مذکر غائب، شروع ہو گئے۔ إِسْبَاغ افعال سے مصدر ہے، پورا پورا کیا۔"}],[607,"اور دوسری روایت ہے کہ مذکورہ راوی نے ابو ہریرہ رضی اللہ عنہ کو وضو کرتے دیکھا کہ انہوں نے چہرہ اور دو ہاتھ دھوئے، قریب تھا کہ شانے تک پانی پہنچ جائے۔ پھر انہوں نے دونوں پاؤں دھوئے یہاں تک پانی پنڈلی تک اونچا کر دیا۔","",{"k":"مسلم (246)، کتاب الطہارۃ، بخاری (136)، نسائی (150)، ابن ماجہ (4306)، احمد (10399)، دارمی (60)"}],[608,"ابو حازم سے منقول ہے کہ اس نے کہا: میں ابو ہریرہ رضی اللہ عنہ کے پس پشت کھڑا تھا اور وہ نماز کا وضو کر رہے تھے پس وہ دھونا اور طویل کر کے ہاتھ بغل تک لے گئے تو میں نے کہا: اے ابو ہریرہ رضی اللہ عنہ! یہ کیسا وضو ہے؟ انہوں نے کہا اے بنو فروخ! تم یہاں موجود ہو اگر مجھے تمہاری موجودگی کا علم ہوتا تو میں ایسا وضو نہ کرتا۔ میں نے اپنے محبوب صلی اللہ علیہ وسلم کو یہ کہتے سنا ہے مومن کا زیور وہاں تک ہوگا جہاں تک اس کا وضو پہنچا ہو گا۔‘‘ (اور نسائی میں لفظ یا بنو فروخ کے علاوہ مثل اس کے ہے)","",{"k":"مسلم (250)، نسائی (149)، اس میں یا نبی فروخ کے لفظ نہیں۔ احمد (8623)","m":"يَا بَنِي فَرُّوخَ یہ حضرت ابراہیم علیہ السلام کی نسل میں سے ہیں، یہ حضرت اسماعیل اور حضرت اسحاق علیہما السلام کے بعد ہوئے ہیں۔ ابو حازم بھی ان میں سے تھے، انہیں اس طرح کہنے کا مقصد یہ تھا کہ ہر بات عوام میں درست نہیں ہوتی فتنہ کا ڈر ہے۔ صاحب علم تو مناسب طریقہ سے ایک عمل کرتے ہیں عوام کی نظر وہاں تک نہیں جاتی۔ (شرح نووی: ۱/ ۱۲۷)","e":"۱۔ ان احادیث میں دلیل موجود ہے کہ چہرے کی سفیدی اور پاؤں کی سفیدی میں طوالت جائز ہے، ہاتھوں میں کندھوں تک لے جائیں پاؤں میں گھٹنوں تک اور چہرے میں گردن کے دونوں کناروں تک دھونا جائز ہے۔ اور یہ بھی ثابت ہوا کہ وضو پہلی امتوں میں تھا۔ مگر اس کے آثار سے سفیدی کا حاصل ہونا یہ خصوصیت صرف اس امت کو حاصل ہے۔ ۲۔ جو یہ کہا گیا ہے کہ مومن کا زیور وضو تک ہے اس کا مطلب ہے کہ وضو سے سفیدی حاصل ہوگی جو نور بن جائے گی جو زیور کی مانند حسن و جمال پیدا کرے گی۔ ۳۔ اس میں وضو پورا پورا کرنے کی بھی ترغیب ہے کہ اعضاء خشک نہ رہیں۔ باقی رہی بات حدیث میں گزرا ہے کہ جو اعضائے وضو تین مرتبہ سے زیادہ دھوئے اس نے ظلم کیا۔\nتو یہ اس کے خلاف نہیں یہاں پورے پورے اعضاء دھونے اور ان کی مقدار بڑھانے کی ترغیب ہے، دھونے کی تعداد میں اضافے کی اجازت نہیں، سفیدی کی طوالت میں اضافہ مستحب ہے، یہ نبی صلی اللہ علیہ وسلم سے ثابت ہے۔"}],[609,"سیدنا عبداللہ بن عباس رضی اللہ عنہما نے کہا: قسم اللہ کی! رسول اللہ صلی اللہ علیہ وسلم نے ہم اہل بیت کو لوگوں سے جدا کر کے کسی چیز میں مخصوص نہیں فرمایا مگر ان تین امور میں۔ آپ صلی اللہ علیہ وسلم نے ہمیں مکمل وضو کا حکم دیا ہے، صدقہ کھانے کی ممانعت فرمائی ہے اور یہ کہ ہم گھوڑی پر گدھا نہ چڑھائیں۔ (نسائی)","",{"k":"نسائی (141)، ترمذی (1701)، ابوداود (808)، ابن ماجہ (426)، احمد (2599)، دارمی (700)، صحیح، البانی: 137","m":"مَا نہیں۔ خَصَّنَا ماضی واحد مذکر غائب ضمیر مفعول یہ ہمیں خاص نہیں کیا۔ فَإِنَّهُ بے شک آپ صلی اللہ علیہ وسلم نے۔ أَنْ یہ ناصبہ ہے، یہ کہ۔ نُسْبِغَ افعال سے مضارع معلوم جمع متکلم، پورا پورا کریں۔ وَلَا نُنْزِيَ افعال سے جمع متکلم مضارع منفی معلوم، ہم جفتی کے لیے نہ چھوڑیں۔ الْحُمُرَ گدھے۔","e":"لوگوں میں مشہور تھا کہ نبی صلی اللہ علیہ وسلم نے اہل بیت کو خاص علم بتایا ہے، سیدنا عبداللہ بن عباس رضی اللہ عنہما اس مشہور عام جھوٹ کی تردید فرما رہے ہیں، کوئی خاص علم نہیں۔ البتہ یہ تین چیزیں خاص ہو سکتی ہیں۔ وہ بھی خاص نہیں کہ دوسروں کو نہ بتائی ہوں۔ دوسروں کو بھی بتائی ہیں۔ ہمیں زیادہ تاکید سے بتائی ہیں کیونکہ ہمیں یہ خصوصیت حاصل ہے۔ (۱) صدقہ نہ کھائیں، یہ آپ نے سب کو بتا رکھا تھا کہ یہ آل محمد صلی اللہ علیہ وسلم پر جائز نہیں۔ مگر یہ تاکید اہل بیت کو کر دی کہ تمہارے لیے خاص حکم ہے کہ تم پر صدقہ و زکوۃ کھانا حلال نہیں۔ (۲) آپ صلی اللہ علیہ وسلم نے احتیاط کے پیش نظر کہا تھا کہ خچر کی نسل حاصل کرنے کے لیے گدھے کو گھوڑی پر جفتی کے لیے نہ چھوڑنا، یہ سب کے لیے تھا۔ مگر اہل بیت کو اس کی خصوصی تاکید کر دی۔ مولانا عطاء اللہ حنیف بھوجیانی رحمہ اللہ فرماتے ہیں، خچر حرام نہیں کہ اسے تیار نہ کیا جائے بس اس کی نسل کو دوگلے پن سے بچانا مقصد ہے۔ اس کی دلیل یہ ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے خچر پر سواری کی اور قرآن پاک نے اسے اللہ کی قدرت کی تعریف کے تحت بیان کیا ہے۔ اگر یہ ناجائز ہوتا تو اسے بطور جمال پیش نہ کیا جاتا۔ (تعلیقات نسائی: ۱/ ۲۰، کتاب الطہارۃ باب الامر باسباغ الوضو ۸۔ ۹) (۳) وضو پورا پورا کرنے میں بھی یہی صورت ہے کہ سب کو تاکید ہے کہ وضو پورا کریں جگہ خشک نہ رہے مگر اہل بیت کو خاص طور پر کہا گیا ہے کہ وضو کے اعضا کا خاص خیال رکھیں کوئی عضو دھونے سے ادھورا نہ رہ جائے۔"}],[610,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور اس نے کہا: مکمل وضو کیسا ہے؟ پس آپ صلی اللہ علیہ وسلم اس وقت خاموش رہے یہاں تک کہ نماز کا وقت آیا اور آپ صلی اللہ علیہ وسلم نے پانی طلب کیا، دونوں ہاتھ دھوئے، ناک میں پانی ڈال کر ناک جھاڑا، منہ میں پانی ڈالا، منہ تین بار دھویا اور دونوں بازو تین تین بار دھوئے، سر کا مسح کیا اور دونوں پاؤں دھوئے پھر اندر کے نیچے پانی چھڑکا اور فرمایا: ’’یہ مکمل وضو ہے۔‘‘ (الموصلی اور بزار نے نقل کیا۔)","",{"k":"ابو یعلیٰ بزار: 6589۔ ابو معشر راوی اس میں آیا ہے، فضائل یا رقت آمیز واقعات اور مغازی میں اس کی حدیث لکھی جاتی ہے، احکام میں نہیں، اس کے بقیہ راوی صحیح کے راوی ہیں۔ ہیثمی: 1221۔"}],[611,"معاویہ بن قرہ اپنے باپ سے وہ اس کے دادا سے نقل کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ایک ایک بار وضو کیا۔ پس فرمایا: ’’یہ وہ وضو ہے جس کے بغیر اللہ تعالیٰ نماز قبول ہی نہیں کرتا۔‘‘ پھر دوسرے موقع پر دو دو بار وضو کیا اور فرمایا: ’’جس نے اس طرح وضو کیا اللہ تعالیٰ اس کا اجر دو بار دو گنا کرے گا۔‘‘ پھر تین تین بار وضو کیا اور فرمایا: ’’یہ ہے مکمل وضو اور یہ میرا وضو ہے اور ابراہیم خلیل اللہ علیہ السلام کا وضو ہے۔‘‘ (الاوسط کمزور سند کے ساتھ طویل روایت ہے)","",{"k":"طبرانی اوسط، اس میں عبدالرحیم بن زید متروک ہے اور اس کا باپ بھی مختلف فیہ ہے۔"}],[612,"سیدنا انس رضی اللہ عنہ نے کہا: نبی کریم صلی اللہ علیہ وسلم ایک صاع سے پانچ سیر پانی کے ساتھ غسل کرتے تھے اور آپ صلی اللہ علیہ وسلم وضو ایک سیر پانی سے کرتے تھے۔","",{"k":"بخاری (201)۔ مسلم (325)۔ نسائی (345)۔ ابوداود (95)۔ احمد (13588)۔ دارمی (689)۔","m":"بِالصَّاعِ واحد اس کی جمع أَصُعٌ ہے، یہ ایک برتن ہے جس میں پانچ رطل پانی آ جاتا ہے۔ (۲ کلو ۱۰۰ گرام) کا ہوتا ہے۔ أَمْدَادٍ اس کا واحد مُدٌّ ہے، یہ صاع کا چوتھا حصہ ہے۔ تقریباً آدھا کلو۔"}],[613,"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم پانچ پیالوں سے غسل کرتے اور ایک پیالہ سے وضو کرتے تھے۔","",{"k":"نسائی (229)۔ بخاری (201)۔ مسلم (325)۔ ترمذی (609)۔ ابوداود (95)۔ احمد (13679)۔ دارمی (689)۔","m":"مَكُّوكٍ اس کی جمع مَكَاكِيُّ یہ بھی مد ہی جتنا ہوتا ہے۔"}],[614,"سیدنا انس رضی اللہ عنہ کی ایک روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’وضو کے لیے دو رطل پانی کفایت کرتا ہے۔‘‘","",{"k":"ترمذی (609)۔ ابوداود (95)۔ احمد (12428)۔ صحیح 499۔","m":"يُجْزِئُ افعال سے مضارع معلوم واحد مذکر غائب، کفایت کرتا ہے۔ رِطْلَانِ اس کا واحد رِطْلٌ ہے۔ یہ بھی تقریباً ساڑھے سات چھٹانک ہے، دو رطل تقریباً چودہ، پندرہ چھٹانک پانی ہوا۔"}],[615,"سیدنا انس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم ایک برتن سے وضو کرتے جس میں دو رطل پانی سماتا تھا اور ایک پیمانے کے ساتھ غسل کرتے تھے۔","",{"k":"ابوداود (95)۔ یہ تو ضعیف ہے۔ البانی: 17۔ مگر یہ بخاری (201)۔ مسلم (325)۔ ترمذی (609)۔ نسائی (345)۔ احمد (13679)۔ دارمی (689) میں بھی آتی ہے۔","m":"يَسَعُ، عَلِمَ سے مضارع معلوم واحد مذکر غائب، سما جاتا ہے، پورا آتا ہے۔"}],[616,"سیدہ ام عمارہ رضی اللہ عنہا سے منقول ہے کہ آپ صلی اللہ علیہ وسلم نے وضو کیا مد کی دو تہائی پانی سے۔","",{"k":"نسائی (74)۔ ابوداود (94)۔ صحیح، البانی: 72۔","m":"فَأُتِيَ ماضی مجہول واحد مذکر غائب، لایا گیا۔ قَدْرَ یہ مصدر ہے، مفعول مطلق ہے اس لیے منصوب ہے، اندازہ۔ ثُلُثَيِ نون اضافت کی وجہ سے گرا ہے، دو تہائی۔ یہ تقریباً تین چھٹانک بنتا ہے۔"}],[617,"سیدہ ربیع بنت معوذ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے گھر تشریف لاتے اور ہمارے وضو کا برتن لیتے مد تیسرا حصہ یا چوتھا حصہ ہوگا اور میں آپ صلی اللہ علیہ وسلم پر پانی ڈالتی اور آپ صلی اللہ علیہ وسلم تین تین بار وضو کرتے تھے۔ (دارمی)","",{"k":"دارمی (690)۔ ابوداود (126)۔ ابن ماجہ (418)۔ احمد (26475)۔","m":"يَأْتِينَا مضارع معلوم واحد مذکر غائب، ضمیر جمع متکلم مفعول بہ ہمارے پاس آتے۔ فَآخُذُ یہ مضارع معلوم واحد متکلم، میں پکڑتا ہوں۔ مِيضَأَةً یہ اسم ظرف ہے، وضو کا برتن۔ فَأَسْكُبُ مضارع معلوم واحد متکلم، میں ڈالتی۔"}],[618,"سیدنا عبداللہ بن زید رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہمارے گھر تشریف لائے پس ہم نے ایک تانبے کے برتن میں آپ صلی اللہ علیہ وسلم کے لیے پانی نکالا تو آپ صلی اللہ علیہ وسلم نے وضو کیا۔ (ابوداود)","",{"k":"ابوداود (100)۔ صحیح، البانی: 91۔ بخاری (197)۔ ابن ماجہ (471)۔ دارمی (694)۔","m":"فَأَخْرَجْنَا ماضی جمع متکلم، ہم نے نکالا۔ تَوْرٍ پتھر کا بنا ہوا برتن جو ہنڈیا کے برابر ہوتا ہے، تھال۔ صُفْرٍ پیتل۔","e":"ان احادیث میں وضو اور غسل کے لیے پانی کی مقدار بیان ہوئی ہے ان میں انداز بتایا گیا ہے کوئی ایک وزن مراد نہیں۔ (۱) وضو میں استعمال ہونے والے پانی کی مقدار میں مختلف احادیث آئی ہیں۔ علامہ شوکانی رحمہ اللہ بہت عمدہ فیصلہ دیتے ہیں، وضو کے اعضاء دھونے میں ایک مد (صاع کا چوتھا حصہ جو کہ تقریباً آدھا کلو ہے) پانی ہو یا اس سے کم ہو یا زیادہ ہو، وضو کے پانی کی مقدار کافی ہے۔ اصل تو یہ ہے کہ اعضائے وضو دھل جائیں۔ اگر اس مقدار سے زیادہ ہو، تب بھی ٹھیک ہے، کم پانی ہو تب بھی ٹھیک ہے۔ بشرطیکہ اسراف کی حد تک پانی ضائع نہ ہو۔ (۲) اسی طرح غسل میں ایک صاع ہو یا کم یا اس سے زیادہ ہو، اعتبار ہو گا کہ بدن دھل جائے، یہ نہ ہو کہ نہانے کے اعضاء تر نہ ہوں اور نہ ہی اسراف سے پانی بہایا گیا ہو۔ (مرعاۃ: ۱/۵۰۱) (۳) ان احادیث میں فضول پانی گرانے سے احتیاط کی دلیل ہے کہ وضو کرتے ہوئے یا نہاتے ہوئے پانی ضائع نہ کیا جائے۔"}],[619,"سیدنا عبداللہ ابن عمرو بن العاص رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم سعد رضی اللہ عنہ کے پاس سے گزرے جب وہ وضو کر رہے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا یہ اسراف کیسا ہے؟ تو انہوں نے کہا کیا وضو میں بھی اسراف ہوتا ہے؟ فرمایا: ’’ہاں خواہ تو جاری نہر سے وضو کرتا ہو۔‘‘","",{"k":"ابن ماجہ (425)۔ احمد (7025)۔ ضعیف، البانی: 96۔"}],[620,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کا ایک کپڑا تھا جس کے ساتھ وضو کے بعد اعضاء خشک کرتے تھے۔ (ترمذی)","",{"k":"ترمذی (53)۔ ضعیف الاسناد، البانی: 7۔"}],[621,"سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم نے وضو کے بعد اپنے کپڑے کے کنارے کے ساتھ چہرہ صاف (خشک) کیا۔","",{"k":"ترمذی (54)۔ ضعیف الاسناد، البانی: 8۔"}],[622,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اس کی نماز نہیں جس کا وضو نہ ہو اور اس کا وضو نہیں جس نے اللہ تعالیٰ کے نام سے ابتدا نہ کی ہو۔ (ابوداود)","",{"k":"ابوداود (101)۔ ابن ماجہ (399)۔ صحیح، البانی: 92۔","m":"لَا صَلَاةَ نہیں نماز، یہ لائے نفی جنس کے لیے ہے کمال کی نفی کے لیے نہیں۔","e":"۱۔ وضو کرتے وقت شروع میں بسم اللہ الرحمن الرحیم پڑھنا (یا صرف بسم اللہ پڑھنا بھی جائز ہے) یہ وضو کے لیے شرط ہے اس کے بغیر وضو نہیں ہوتا۔ دوسری دعا وضو سے پہلے پڑھنے کی بسم اللہ والحمد للہ بھی ثابت ہے، آگے آرہی ہے۔ شاہ ولی اللہ رحمہ اللہ فرماتے ہیں: أَنَّ التَّسْمِيَةَ رُكْنٌ أَوْ شَرْطٌ (حجۃ اللہ البالغہ) ’’بسم اللہ پڑھنا وضو میں رکن یا شرط ہے۔‘‘ ثابت ہوا اسے نفی کمال پر قیاس کرنا یا مجاز مراد لینا یہ سب غلط ہے، بسم اللہ کے بغیر وضو ہی نہیں ہوتا۔"}],[623,"ان ہی سے مرفوع روایت ہے: جس نے وضو کی ابتداء میں اللہ کو یاد کیا اس کا تمام جسم پاک ہو جاتا ہے اور جس نے اللہ تعالیٰ کو یاد نہ کیا تو صرف وضو کے اعضاء ہی پاک ہوتے ہیں۔","",{"k":"رزین، دار قطنی اور بیہقی نے بھی اسے بیان کیا ہے، اس میں ابوبکر داھری، عبداللہ بن حکم متروک ہے، وضع کی طرف منسوب ہے۔ ضعیف جدًا۔"}],[624,"سیدنا ابو موسیٰ رضی اللہ عنہ نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو آپ صلی اللہ علیہ وسلم وضو کر رہے تھے پس میں نے آپ صلی اللہ علیہ وسلم کو یہ کہتے سنا: اے اللہ! میرے گناہ معاف کر میرے گھروں میں وسعت کر اور میرے رزق میں برکت ڈال۔","",{"k":"رزین، رواه النسائی باب ما يقول بعد الفراغ من الوضو و ابن السنى، باب ما يقول بين طهرانی وضوئه باسناد صحيح (فقه السنه)","m":"وَوَسِّعْ تفعیل سے امر حاضر واحد مذکر، کشادہ کر دے۔ وَبَارِكْ مفاعلہ سے امر واحد مذکر حاضر، برکت کر دے۔","e":"سیدنا ابو موسیٰ اشعری رضی اللہ عنہ بیان کرتے ہیں، جب میں نے آپ صلی اللہ علیہ وسلم سے یہ دعا سنی تو میں نے کہا، اے اللہ کے نبی صلی اللہ علیہ وسلم! میں نے آپ کو یہ دعا کرتے ہوئے سنا ہے تو آپ صلی اللہ علیہ وسلم نے فرمایا، اس دعا میں کونسی چیز باقی رہ گئی ہے یعنی گناہ کی بخشش سے دنیا و آخرت کی بھلائی آگئی اور برکت ملی اور گھر کشادہ ہو تو آسودگی ملی اور رزق میں برکت ہوئی تو سکون و قرار ملا۔ اس لیے فرمایا کوئی بھی دنیا و آخرت کی خیر ایسی نہیں جو اس میں نہ ہو۔ امام نسائی رحمہ اللہ نے اس حدیث سے یہ مسئلہ حاصل کیا ہے کہ یہ دعا وضو سے فراغت کے بعد پڑھی جائے مگر ابن سنی رحمہ اللہ نے یہ استدلال کیا ہے کہ یہ دعا وضو کے دوران کی جائے۔ امام نووی رحمہ اللہ کا فیصلہ بہت درست ہے کہ دونوں جگہ پر یہ دعا پڑھی جاسکتی ہے۔ یاد رہے کہ اس کے علاوہ ہر عضو وضو دھوتے ہوئے کوئی دعا ثابت نہیں۔ (فقہ السنہ سید سابق: ۱/۴۳)"}],[625,"سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اے ابوہریرہ! جب تو وضو کرے تو کہا کر: بسم اللہ والحمد للہ تو تیرے کرام کاتبین فرشتے تیری نیکیاں لکھنے سے اس وقت تک فارغ نہیں ہونگے جب تک تیرا یہ وضو ٹوٹ نہیں جاتا۔‘‘ (الصغیر)","",{"k":"طبرانی صغیر و اسناده حسن، هیثمی: 1112۔","m":"حَفَظَتَكَ اس کا واحد حَافِظٌ ہے، تیرے نگران فرشتے۔ لَا تَسْتَرِيحُ استفعال سے مضارع منفی، واحد مؤنث غائب، آرام نہیں کرتے یعنی لکھتے رہتے ہیں، تھکتے نہیں۔ تُحْدِثَ افعال سے مضارع معلوم واحد مذکر حاضر تو بے وضو ہو جائے۔","e":"اس حدیث سے ثابت ہوا کہ وضو کرنے سے پہلے یہ دعا پڑھنی بھی جائز ہے، صرف بسم اللہ الرحمن الرحیم بھی جائز ہے۔ اس کے پڑھنے سے بے وضو ہونے تک فرشتے نیکیاں لکھتے رہتے ہیں کیونکہ اس میں اللہ تعالیٰ کی الوہیت اور حمد بیان ہوئی ہے۔"}],[626,"ابو جنون نے کہا کہ میں نے علی رضی اللہ عنہ کو وضو کا پانی ڈالتے دیکھا، تو میں جلدی کر کے پانی ڈالنے کے لیے بڑھا: پس علی رضی اللہ عنہ نے کہا: ابو جنون ٹھہر جاؤ۔ میں نے عمر رضی اللہ عنہ کو وضو کا پانی ڈالتے دیکھا تو میں آگے بڑھا تا کہ پانی ڈالوں۔ تو عمر رضی اللہ عنہ نے کہا ابوالحسن ٹھہر جاؤ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو وضو کا پانی لیتے دیکھا تو میں آگے بڑھا تا کہ میں پانی ڈالوں پس آپ صلی اللہ علیہ وسلم نے فرمایا: اے عمر! ٹھہر جاؤ! میں نا پسند کرتا ہوں کہ مجھے وضو کرانے میں دوسرا انسان شامل ہو۔‘‘ (موصلی و بزار ابوالجنون ضعیف)","",{"k":"ابو یعلی: 231، بزار، اس میں ابوالجنون راوی ضعیف ہے۔ ہیثمی: 147."}],[627,"وابصہ بن معبد رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم سے ہر چیز کے بارے میں پوچھا حتی کہ اس میل کے بارے میں جو ناخنوں کے درمیان ہوتی ہے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’شک والی چیز کو چھوڑ دو اور یقین والی کو اختیار کرو۔‘‘","",{"k":"طبرانی کبیر، اس میں طلحہ بن زید الرقی ہے۔ مجمع علی ضعفه، ہیثمی: 1226."}],[628,"سیدنا ابو ہریرہ رضی اللہ عنہ مرفوع بیان کرتے ہیں کہ فرمایا: ’’جب تم میں سے کوئی آدمی وضو کر چکا ہو تو وہ اپنی انگلیوں کے درمیان تشبیک نہ کرے۔‘‘ (الاوسط، اس کا راوی عتیق بن یعقوب ہے)","",{"k":"طبرانی اوسط: 840، وفیہ عتیق بن یعقوب ولم ارمن ذکرہ وبقیہ رجالہ رجال الصحیح ہیثمی: 1232."}],[629,"یزید بن ابی عبید نے کہا: جب سلمہ بن اکوع رضی اللہ عنہ وضو کرتے تو تھوڑی سی کستوری لے کر ہاتھ میں مسل کر اپنی داڑھی میں لگاتے تھے۔ (الکبیر)","",{"k":"طبرانی کبیر: 6220، والاوسط ورجالہ رجال الصحیح.","m":"الْمِسْكَ کستوری۔ فَيُدِيفُهُ افعال سے مضارع معلوم واحد مذکر غائب، ملنا۔","e":"اس سے ثابت ہوا کہ وضو کے طریقوں میں یہ بھی شامل ہے کہ وضو سے فارغ ہو کر داڑھی وغیرہ میں خوشبو لگائی جائے، یہ سنت ہے کہ نماز سے پہلے عطریات لگائی جائیں کیونکہ لوگوں اور فرشتوں نے حاضر ہونا ہوتا ہے۔"}],[630,"عبد الملک بن عمیر نے کہا میں نے سنا ہے: شبیب بن ابوروح سے جو ذی الکلاع قبیلے سے ہیں کہ اس نے نبی کریم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی پس آپ صلی اللہ علیہ وسلم نے سورت الروم تلاوت کی تو آپ صلی اللہ علیہ وسلم کو قراءت میں تردد ہوا۔ جب سلام پھیرا تو فرمایا: ہم پر قرآن بھلایا گیا ہے: کچھ لوگ جو ہمارے ساتھ نماز پڑھتے ہیں اچھی طرح وضو نہیں کرتے۔ پس جو ہمارے ساتھ نماز پڑھے تو وہ اچھی طرح وضو کرے۔‘‘ (احمد)","",{"k":"احمد (15312)، نسائی (947)، ورجالہ رجال الصحیح، ہیثمی: 1241.","m":"عَنْ رَجُلٍ ایک آدمی سے صحابی رضی اللہ عنہ کے نام کا علم نہ ہونا حدیث میں نقص پیدا نہیں کرتا۔ فَتَرَدَّدَ تفعل سے ماضی واحد مذکر غائب، تردد میں پڑ گئے، شک کا شکار ہوئے۔ يَلْبِسُ عَلَيْنَا مضارع معلوم واحد مذکر غائب، ہمارے اوپر قراءت کو خلط ملط کرتے ہیں۔ لَا يُحْسِنُونَ افعال سے مضارع معلوم منفی، جمع مذکر غائب، اچھا نہیں کرتے۔","e":"۱۔ اس حدیث سے نماز فجر میں سورت الروم پڑھنے کی مشروعیت کی دلیل ہے۔ ۲۔ اس میں یہ تاکید ہے کہ وضو پورا پورا کیا جائے اس میں کسی قسم کا نقص نہ ہو۔ ۳۔ یہ ثابت ہوا کہ صحبت اور ہمنشینی تاثیر رکھتی ہے کہ اکمل لوگ اتنے باصفا ہوتے ہیں کہ ان کے ساتھی کی روحانی کوتاہی بھی ان کی چمک میں اثر دکھاتی ہے اور داغ لگاتی ہے۔"}],[631,"انس رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہر نماز کے لیے تازہ وضو کرتے تھے۔ کہا گیا: اے انس! تم صحابہ رضی اللہ عنہم کیا کرتے تھے؟ انہوں نے کہا: ہم میں سے ہر ایک کو سابقہ وضو ہی کفایت ہوتا تھا جب تک بے وضو نہ ہوتا۔","",{"k":"بخاری (214)، ترمذی (60)، نسائی (132)، ابوداود (171)، ابن ماجہ (509)، احمد (13323)، دارمی (720).","m":"يُجْزِئُ افعال مضارع معلوم واحد مذکر غائب، کفایت کرتا ہے۔ أَحَدَنَا ہمارا ایک۔ یہ مفعول بہ ہے مَا جب تک۔ لَمْ يُحْدِثْ نفی جحد واحد مذکر غائب، بے وضو نہ ہو۔"}],[632,"بریدہ رضی اللہ عنہ نے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مکہ کی فتح کے دن کئی نمازیں ایک وضو سے ادا کیں تو عمر رضی اللہ عنہ نے عرض کی: آپ صلی اللہ علیہ وسلم نے آج وہ عمل کیا جو پہلے آپ صلی اللہ علیہ وسلم نہیں کیا کرتے تھے تو آپ صلی اللہ علیہ وسلم نے فرمایا: اے عمر میں نے عمداً ایسا کیا ہے۔","",{"k":"مسلم (277)، کتاب الطہارۃ، ترمذی (61)، نسائی (133)، ابوداود (172)، ابن ماجہ (510)، احمد (22520)، دارمی (659).","m":"صَنَعْتَ ماضی سے واحد مذکر حاضر، آپ نے کیا۔ عَمْدًا جال یا تمیز کی بنا پر منصوب ہے، مسئلہ کی اہمیت کے پیش نظر اسے مقدم رکھا ہے۔","e":"پہلی حدیث سے ثابت ہوتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم ہر نماز کے لیے وضو کرتے تھے اور صحابہ کرام رضی اللہ عنہم جب تک وضو ٹوٹتا نہیں تھا۔ اس وقت تک وضو نیا نہیں کرتے تھے۔ دوسری حدیث سے ثابت ہوتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک وضو سے کئی نمازیں ادا فرمائی تھیں۔ ان دونوں میں مطابقت یہ ہے کہ پہلے آپ افضل تصور کرتے ہوئے اس پر عمل پیرا تھے کہ وضو ہو یا نہ ہو پھر بھی نیا وضو کرتے تھے۔ جب آپ صلی اللہ علیہ وسلم نے غور فرمایا کہ اس طرح میری امت پر مشقت آئے گی تو ان کی آسانی کے لیے اس پر عمل شروع کر دیا کہ اگر وضو برقرار ہوتا تو زیادہ نمازیں پڑھ لیتے تھے۔ اگر نہ ہوتا تو پھر کرتے تھے وگرنہ آپ کے لیے نیا وضو کرنا کوئی مشکل نہ تھا۔ ۲۔ اس سے ثابت ہوا کہ موزوں پر مسح کرنا سنت ہے۔"}],[633,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم حسب طاقت دائیں طرف سے ابتدا کرنا پسند کرتے تھے اپنے تمام امور میں۔ طہارت کرنے، کنگھی کرنے اور جوتا پہننے میں۔","",{"k":"نسائی (112)، صحیح، البانی: 109، بخاری (5926)، مسلم (268)، ترمذی (608)، ابوداود (4140)، ابن ماجہ (401)، احمد (25235).","m":"يُحِبُّ افعال سے مضارع معلوم واحد مذکر حاضر، پسند کرتے ہیں۔ اَلتَّيَامُنَ تفاعل سے مصدر ہے، دائیں جانب۔ مَا اسْتَطَاعَ استفعال سے ماضی واحد مذکر غائب، جب تک طاقت ہوتی۔ طُهُورِهِ پاکیزگی اختیار کرنے میں، مراد وضو ہے۔ وَنَعْلِهِ جوتا پہننے میں۔ وَتَرَجُّلِهِ تفعل سے، بالوں میں کنگھی کرنے میں۔","e":"ان تینوں کے بارے میں اہتمام کی وجہ سے دائیں جانب کے استعمال کرنے کا آیا ہے کیونکہ طہارت عبادات کی کنجی ہے اس لیے اس کا ذکر کیا، انسان کا تعلق یا اوپر والی جہت سے ہے، یا نیچے والی جہت سے ہے یا اطراف سے ہے، اس میں ہر ایک کی طہارت اور صفائی کا ذکر آجاتا ہے۔ جو چیز بھی تکریم اور زینت سے تعلق رکھتی ہے اسے دائیں جانب سے شروع کرنا مستحب ہے، جو ان کے برعکس ہیں ان میں بائیں جانب مستحب ہے۔"}],[634,"سیدنا علی بن طلق رضی اللہ عنہ نے کہا ایک اعرابی نے کہا: یا رسول اللہ! جب ہم میں سے کوئی شخص صحراء میں ہو اور ہوا خارج ہو اور پانی کی قلت ہو۔ تو پس آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص منہ سے قے کرے تو وضو کرے اور عورتوں سے دبر میں جماع نہ کرو اللہ تعالیٰ حق کی بات سے نہیں شرماتا۔‘‘ (ترمذی و ابوداؤد)","",{"k":"ترمذی (1164)، ابوداود (1005)، دارمی (114)، ضعیف، البانی: 201."}],[635,"سیدنا ابوہریرہ رضی اللہ عنہ مرفوع بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’نہیں لازم آتا وضو مگر آواز سے یا ہوا خارج ہونے سے۔‘‘","",{"k":"ترمذی (74)، صحیح، البانی: 64، مسلم (362)، ابوداود (177)، ابن ماجہ (515)، احمد (9743)، دارمی (721)."}],[636,"ایک روایت میں ہے: ’’جب تم میں سے کوئی آدمی مسجد میں ہو اور اس کو اپنی سرین کے درمیان ہوا محسوس ہو تو وہ مسجد سے خارج نہ ہو یہاں تک کہ آواز سنے یا وہ بدبو پائے۔‘‘","",{"k":"ترمذی (75)، مسلم (362)، ابوداود (177)، ابن ماجہ (515)، احمد (9743)، دارمی (721).","m":"فَوَجَدَ، ضَرَبَ سے ماضی واحد مذکر غائب، وہ پائے۔ أَلْيَتَيْهِ یہ تثنیہ ہے، اس کا واحد أَلْيَةٌ ہے، چوتڑ۔ فَلَا يَخْرُجُ نہی واحد مذکر غائب، نہ نکلے یعنی مسجد میں بیٹھا ہو تو وضو کے لیے باہر نہ جائے۔ اس زمانہ میں مسجد میں وضو کا انتظام نہیں ہوتا تھا، باہر جانا پڑتا تھا۔ رِيحًا یعنی نکلنے والی ہوا کی بو پائے۔"}],[637,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی شخص نماز میں ہوتا ہے تو شیطان آکر اس کو مانوس کرتا ہے جیسے ایک آدمی اپنے چوپائے کو مانوس کرتا ہے جب انسان اس کے ساتھ تسکین پکڑتا ہے تو اس کی سرین کے درمیان کوز مارتا ہے تا کہ اس کو نماز سے فتنے میں ڈال دے پس اگر کوئی شخص یہ چیز محسوس کرے تو وہ نماز ترک نہ کرے یہاں تک کہ آوازیں سنے یا وہ ریح محسوس کرے۔‘‘","",{"k":"احمد (8169)، عند ابی باختصار: 177، رجال احمد رجال الصحیح، ہیثمی: 1246، مسلم (362)، ترمذی (47).","m":"فَأَبَسَ، ضَرَبَ سے ہے، اسے تابع کرتا ہے۔ سَكَنَ لَهُ، نَصَرَ سے اس شیطان کے لیے خاموش ہو گیا، یعنی شیطان اس شرارت سے باز آئے گا تو پھر دوسری شروع کر دیتا ہے۔ أَضْرَطَ افعال سے ماضی معلوم واحد مذکر غائب، گوز کرنے کا وہم ڈالتا ہے، اس کے اندر بناوٹی گوز کرنے اور ہوا مارنے کی کیفیت پیدا کرتا ہے۔ لِيَفْتِنَهُ، ضَرَبَ سے مضارع معلوم واحد مذکر غائب، لام کئی نے نصب دیا ہے۔ تا کہ فتنہ میں ڈالے۔"}],[638,"اور ایک روایت میں ہے کہ بندہ جب شیطان کے ساتھ لگ کر تسکین پاتا ہے تو وہ اس کو تنگ باندھتا اور لگام ڈالتا ہے۔ ابو ہریرہ رضی اللہ عنہ نے کہا: تم دیکھ سکتے ہو جس کو تنگ ڈالتا ہے وہ آدمی ایک جانب کو مائل ہو جاتا ہے اور جس کو لگام ڈالتا ہے تو تم اس کا منہ کھلا ہوا دیکھ سکتے ہو وہ اللہ کو یاد نہیں کر رہا ہوتا۔","",{"k":"احمد (8170)، دوسری 638 والی تخریج ہے.","m":"زَنَقَ، نَصَرَ اور ضَرَب دونوں بابوں سے آتا ہے، گھوڑے کے جبڑے کے نیچے بند باندھنا۔ مَزْنُوقَ اسی سے اسم مفعول ہے۔ أَلْجَمَهُ افعال سے ماضی واحد مذکر غائب، لگام ڈالی اس نے۔ فَتَرَاهُ، رُؤْيَةٍ سے مضارع معلوم واحد مذکر حاضر ہے تو اسے دیکھتا ہے۔ مَائِلًا، مَیْلَان سے اسم فاعل ہے، مفعول یہ ہے منصوب۔ ایک طرف مائل ہونا۔ فَفَاتِحٌ، فَتْح سے اسم فاعل واحد مذکر ہے، کھولنے والا۔ فَاهُ منہ اپنا۔"}],[639,"سیدنا ابن مسعود رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: شیطان تمہارے کسی فرد کے پاس نماز پڑھتے وقت آتا ہے اور اس کے دبر سے کوئی بال پکڑتا ہے تو آدمی سمجھتا ہے وہ بے وضو ہو چکا ہے پس جب یہ کیفیت ہو تو نماز سے نہ پھر یہاں تک کہ آواز سنے یا ہوا خارج ہوتے پائے۔‘‘ (الکبیر بسند ضعیف)","",{"k":"طبرانی کبیر، اس میں حجاج بن ارطاۃ ثقہ تو ہے مگر یہاں تدلیس کی ہے، استاد سے حدیث سننے کی صراحت نہیں کی۔"}],[640,"ایک روایت میں ہے: شیطان آدمی کے ساتھ نماز میں نرمی سے پیش آتا ہے تا کہ وہ اس کی نماز توڑ دے جب اس کو تھکا دیتا ہے تو اس کی دبر میں پھونک مارتا ہے: تم میں سے جب کوئی اس کی یہ حرکت محسوس کرے تو۔۔۔۔۔ سابقہ حدیث کی طرح۔‘‘","",{"k":"طبرانی کبیر: 9231 ورجاله موثقون، هيثمي: 1252۔","m":"لَيَلْطُفُ تفعیل سے مضارع معلوم واحد مذکر غائب، حیلہ سازی کرتا ہے۔ أَعْيَاهُ افعال سے ماضی واحد مذکر غائب، تھکا دیا۔ یعنی انسان، شیطان کا حیلہ نہیں چلنے دیتا اس سے بے بس کر دیتا ہے۔ أَحَسَّ افعال سے ماضی واحد مذکر غائب، محسوس کرے۔ بِنَحْوِهِ یعنی حدیث ۶۳۹ والی مانند ہے کہ جب تک یقین نہ ہو وضو کے لیے نہ جائے۔"}]])